INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_001', 'lesson_note', '강의 개요', '조창훈', '본 강의는 3월 모의고사 31-34번 지문인 고전 소설 \'숙매청심록\'을 심층적으로 분석합니다. 수험생들이 처음 접할 수 있는 작품의 인물 관계와 사건을 쉽게 파악할 수 있도록, 유사한 고전 소설의 전형적인 \'모델\'(화소, 모티프)을 활용하는 독해 전략을 제시합니다. 이를 통해 지문 이해도를 높이고 문제를 효과적으로 해결하는 것을 목표로 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_002', 'lesson_note', '핵심 독해 전략: \'모델\'의 활용', '조창훈', '- 고전 소설을 많이 읽어 전형적인 이야기 구조나 모티프(화소)인 **\'모델\'**을 머릿속에 구축해야 합니다.\n- \'숙매청심록\'과 같이 처음 보는 작품이라도, 보기의 내용을 바탕으로 익숙한 모델을 떠올리면 내용을 예측하며 읽을 수 있습니다.\n- 이 작품의 핵심 모델은 **공적 명령(황제의 결혼 명령)과 개인의 사적 관계(기존의 혼약) 사이의 충돌**입니다. 이 모델은 다른 여러 고전 소설에서도 흔히 발견되는 구조입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_003', 'lesson_note', '\'숙매청심록\'의 기본 갈등 구조', '조창훈', '- **공적 권력(황제)의 명령**으로 인해 주인공이 **개인 간의 혼약**을 지키지 못하는 상황이 발생합니다.\n- 주인공(이중백)은 이미 혼약한 상대(현녀)가 있음에도 황제의 명으로 다른 여성(군주)과 결혼해야 하는 위기에 처합니다.\n- 이 작품의 특이점은 이러한 위기 상황에서 **누군가(이중백의 어머니)가 \'대응\' 방안을 제시**한다는 점입니다. 이는 단순히 운명에 순응하는 다른 소설과 차별화되는 지점입니다.\n- 제시된 대응은 생존을 우선시하는 전략적 판단에 기반하며, 이 과정에서 고난이 따르지만 결국에는 원래의 인연이 이루어질 것(지연)을 암시합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_004', 'lesson_note', '주요 인물 관계 분석', '조창훈', '- **천자(황제, 상)**: 최고 권력자. 이중백에게 군주와의 혼인을 명함.\n- **주태후**: 천자의 계모. 노왕의 어머니이자 군주의 할머니. 손녀인 군주의 부탁을 들어주고 혼사를 추진하는 핵심 인물.\n- **노왕**: 노나라의 왕. 주태후의 아들이자 천자의 배다른 형제. 군주의 아버지.\n- **군주**: 노왕의 딸. 천자의 조카. 길에서 우연히 본 이중백에게 반해 할머니(주태후)를 통해 강제로 혼인함.\n- **이중백**: 남자 주인공. 현녀와 혼약을 맺었으나 황제의 명으로 군주와 결혼하게 됨.\n- **현녀(오소저)**: 이중백의 본래 약혼녀. 오상서의 딸.\n- **시랑(이중백의 아버지)**: 아들의 강제 혼인과 약혼자 집안과의 신의 사이에서 고뇌함.\n- **심부인(이중백의 어머니)**: 아들과 현녀, 그리고 가문 모두를 살리기 위해 현실적인 해결책(현녀를 잠시 숨기는 것)을 제시함.\n- **주연 승상**: 주태후와 같은 주씨. 이중백의 죄를 사해주는 대신 제나라로 사신을 보내고, 그사이 현녀를 노국 세자의 후궁으로 보내려는 계책을 냄.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_005', 'lesson_note', '고전 소설 용어 및 배경지식', '조창훈', '- **황제와 왕의 구분**: 천자(황제)는 모든 나라의 최고 통치자이며, 왕은 봉건제 하에서 특정 지역(나라)을 다스리는 제후입니다.\n- **중국의 봉건 제도**: 황제가 각 지역을 왕이나 공(公)·후(侯)·백(伯)·자(子)·남(男) 등의 작위를 가진 제후에게 맡겨 다스리는 체제.\n- **호칭 정리**:\n    - **상(上)**: 임금, 즉 천자(황제)를 지칭.\n    - **태후(太后)**: 황제의 어머니. (황후는 황제의 아내)\n    - **공주(公主)**: 황제의 정실부인(황후) 소생의 딸.\n    - **옹주(翁主)**: 황제의 후궁 소생의 딸.\n    - **군주(郡主)**: 왕(제후)의 딸. 이 작품에서는 천자의 조카 신분.\n    - **군(君)**: 왕자. (예: 수양대군, 연산군)\n    - **세자(世子)**: 왕위를 계승할 아들. (태자는 황위 계승자)\n    - **상서(尙書), 시랑(侍郎)**: 높은 벼슬의 직책. 상서는 장관급에 해당.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_006', 'lesson_note', '줄거리 심층 분석', '조창훈', '1.  **강제 혼인과 갈등**: 군주가 이중백에게 반해 할머니인 주태후를 통해 천자에게 혼인을 요청하고, 천자의 명으로 이중백은 원치 않는 결혼을 하게 됩니다.\n2.  **이중백의 저항과 투옥**: 결혼 후 이중백이 군주를 멀리하자, 군주는 태후에게 이를 알리고 태후는 천자에게 고변하여 이중백은 감옥에 갇힙니다.\n3.  **이중백 부모의 논의**:\n    - **어머니(심부인)의 제안**: 현녀와 먼저 결혼시키면 두 집안 모두 화를 입을 것이라 주장. 이중백이 군주와 결혼한 후 몰래 현녀를 만나러 다니다 발각되면 더 큰 참화가 닥칠 것을 우려. 따라서, 일단 군주와 결혼시키고 현녀는 잠시 숨겨서 후일을 도모하자고 제안.\n    - **아버지(시랑)의 고뇌**: 현녀의 죽은 아버지(오상서)가 꿈에 나타나 반드시 혼례를 치르라고 당부했던 약속 때문에 결정을 내리지 못하고 고민합니다.\n4.  **주연 승상의 계책**: 주연 승상은 이중백의 죄를 사해주고 제나라에 사신으로 보내 공을 세울 기회를 주는 척하면서, 그 사이에 현녀를 노나라 세자의 후궁으로 보내 이중백과 완전히 떼어놓으려는 음모를 꾸밉니다.\n5.  **계책의 실행**: 이 계책은 태후와 군주의 동의를 얻어 실행됩니다. 이중백은 제나라로 떠나게 되고, 이 과정에서 자신의 집안을 방문한 군주와 집안사람들 사이에 냉랭한 기류가 흐릅니다.\n6.  **이중백의 상황 파악**: 이중백은 자신을 제나라로 보내는 것이 주연과 태후의 계략이며, 현녀를 해치려는 의도임을 간파합니다. (단, 후궁으로 보내려는 구체적인 계획까지는 알지 못함)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_007', 'lesson_note', '34번 문제 풀이 전략', '조창훈', '- **보기의 핵심 파악**: 보기의 내용은 \'공적 명령\'과 \'개인적 혼약\'의 갈등 상황을 설명합니다.\n- **선택지 분석**: 각 선택지를 보기의 개념(공적 권력, 개인 애정 관계 등)과 연결하여 분석합니다.\n- **오답 판별 핵심**:\n    - 이 작품의 \'모델\'상, **황제의 명령(공적 명령)은 거역할 수 없다**는 전제를 따라야 합니다.\n    - 2번 선택지의 "부부의 정은 천자의 위엄이라도 폐하지 못하나이다"라는 구절은, 이중백의 어머니가 \'만약 현녀와 먼저 결혼시킨다면\'이라는 **가정 상황**에서 한 말입니다.\n    - 이는 천자의 명령보다 사적인 신의를 우위에 두자는 결정이 아니라, 그렇게 했을 경우 닥칠 위험(두 집안의 멸문)을 경고하며 그 선택지를 포기하게 만드는 근거입니다.\n    - 따라서, 인물들이 개인 간의 혼약을 공적 명령보다 우위에 두었다고 해석하는 것은 잘못된 분석입니다. 이 모델에서 인물들은 일단 공적 명령에 따를 수밖에 없습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_008', 'lesson_note', '결론 및 핵심 요약', '조창훈', '- \'숙매청심록\'과 같은 고전 소설을 효과적으로 독해하기 위해서는 **전형적인 서사 구조(모델)에 대한 이해**가 필수적입니다.\n- **\'황명(皇命)으로 인한 약혼 파기 및 강제 혼인\'**이라는 모티프를 이해하면, 인물들의 행동(일단 황명에 순응)과 앞으로의 전개(고난 후 원래 인연과 재회)를 예측할 수 있습니다.\n- 인물 관계와 호칭, 당시의 사회·정치적 배경(봉건제 등)에 대한 지식은 지문을 정확하게 이해하는 데 큰 도움이 됩니다. 이러한 배경지식을 바탕으로 인물들의 대사와 행동의 숨은 의도를 파악하는 연습이 중요합니다.\n\n\n# 3월 모의고사 심층 분석 및 고득점 전략 논의');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_009', 'lesson_note', '요약', '조창훈', '이번 3월 모의고사의 이례적으로 낮은 등급컷을 분석하고, 학생들의 시험 운용 전략을 점검하는 회의입니다. 강사는 특히 어려운 시험 상황에서 포기하지 않고 80분 전체를 운용하는 훈련의 중요성을 강조했습니다. 문제의 난이도를 \'잡몹\'과 \'보스\'에 비유하며, 쉬운 문제는 빠르고 정확하게 해결하여 점수와 시간을 확보하고, 어려운 문제는 전략적으로 건너뛰거나 \'레이어\'를 쌓는 방식으로 단계적으로 접근할 것을 주문했습니다. 특히 오답률이 높았던 언어와 매체 39번(길짐승)과 문학 19번 문제를 심층 분석하며, 복잡한 문제를 분해해서 푸는 방법과 잘못 출제된 문제에 대처하는 요령을 구체적인 예시와 함께 설명했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_010', 'lesson_note', '회의 개요', '조창훈', '본 회의는 3월 모의고사 결과에 대한 분석과 향후 학습 전략 수립을 목적으로 진행되었습니다. 주요 내용은 다음과 같습니다:\n\n*   3월 모의고사 등급컷 및 난이도 분석\n*   시험 시간 관리 및 위기 대처 능력의 중요성 강조\n*   \'잡몹\'과 \'보스\' 개념을 활용한 문제 풀이 전략 제시\n*   고난도 문제(언매 39번, 문학 19번) 심층 풀이 및 접근법 교육\n*   다음 수업에서 다룰 내용(수특 도파민 지문) 논의');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_011', 'lesson_note', '주요 논의 사항', '조창훈', '*   **모의고사 난이도**: 화작 1컷 79점, 언매 1컷 76점 등 전반적으로 매우 어려운 시험이었음을 확인했습니다. 강사는 이러한 난이도가 수능에서는 재현되지 않을 것이라며 학생들을 안심시켰습니다.\n*   **시험 운용의 중요성**: 계획대로 풀리지 않더라도 중간에 포기하지 않고 80분을 끝까지 완주하는 연습이 실전에서의 위기관리 능력으로 이어진다고 강조했습니다. 시간 부족 상황에서도 남은 시간 동안 최선의 전략을 세워 1점이라도 더 얻으려는 노력이 중요합니다.\n*   **문제풀이 전략: 잡몹 vs 보스**: 45개의 문제 중 대부분(35~40개)은 비교적 쉬운 \'잡몹\' 문제이며, 이 문제들을 빠르고 정확하게 푸는 것이 기본 점수 확보에 결정적입니다. 소수의 고난도 \'보스\' 문제는 시간을 너무 많이 소모하지 말고, 풀리지 않으면 과감히 건너뛰는 전략이 유효합니다. 보스 문제를 다 틀려도 잡몹 문제만 다 맞히면 2등급 이상 확보가 가능함을 수치적으로 설명했습니다.\n*   **고난도 문제 접근법: 레이어 쌓기**: 어려운 문제는 한 번에 해결하려 하지 말고, 여러 단계(레이어)로 나누어 접근해야 합니다. 선택지나 문제의 조건을 하나씩 적용해나가며 범위를 좁히는 방식이 효과적입니다. 이는 수학 4점짜리 문제를 풀 듯, 국어 문제에도 단계적 사고를 적용하는 훈련이 필요함을 의미합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_012', 'lesson_note', '문제 심층 분석', '조창훈', '### 언어와 매체 39번 (길짐승)\n*   **문제 유형**: 오답률 1위 문법 문제.\n*   **강사의 풀이 전략 (레이어 쌓기)**:\n    1.  **1단계**: 문제의 조건(기억과 니은이 모두 사용)을 보고, 문장 안에 **합성어 두 개**가 있어야 함을 먼저 파악합니다.\n    2.  **2단계**: 선택지 4번과 5번은 합성어가 하나뿐이므로 즉시 제외합니다.\n    3.  **3단계**: 남은 1, 2, 3번 선택지들을 대상으로 \'기억\' 조건(어근+어근)과 \'니은\' 조건(용언 어간+관형사형 전성 어미+체언)을 적용하여 정답을 찾습니다.\n*   **핵심**: 복잡한 조건을 한 번에 처리하려 하지 않고, 가장 판단하기 쉬운 조건(합성어 개수)부터 적용하여 선택지를 줄여나가는 것이 핵심입니다.\n\n### 문학 19번 (김기택, \'어떻게 기억해냈을까\')\n*   **문제 유형**: 시 A, B에 대한 이해를 묻는 문제.\n*   **강사의 비판**: 이 문제는 출제자가 제시된 범위(A, B) 밖의 내용을 근거로 답을 만들고, 현대시 문제에 어울리지 않는 과도한 논리(필요조건)를 요구하는 등 \'신의성실의 원칙\'을 어긴 잘못된 문제라고 강하게 비판했습니다.\n*   **오답 분석 (정답 3번)**: 정답의 근거는 \'오랜 세월을 거쳐야만 생명력이 무르익을 수 있다\'는 필요조건 표현이 시의 내용과 부합하지 않는다는 것입니다. 강사는 시의 내용에서 \'오랜 세월\'과 \'무르익음\'이 함께 나타나긴 하지만, 전자가 후자의 \'필요조건\'이라고 단정할 근거는 없다고 설명했습니다. 이는 법 지문에서나 다룰 법한 엄밀한 논리적 판단입니다.\n*   **결론**: 이런 유형의 문제는 정상적인 사고 과정으로 풀기 어려우므로, 시험장에서 마주쳤을 때 깊이 고민하기보다는 과감히 건너뛰는 것이 현명한 전략이라고 조언했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_013', 'lesson_note', '시험 대비 전략', '조창훈', '*   **쉬운 문제는 쉽게 풀기**: \'잡몹\' 문제에 너무 많은 에너지나 시간을 소모하지 않도록 주의해야 합니다. 신중함이 지나쳐 쉬운 문제에서 시간을 낭비하는 습관을 버려야 합니다.\n*   **어려운 문제는 과감히 버리기**: \'보스\'급 문제에 부딪혔을 때, 해결이 어렵다고 판단되면 미련 없이 넘어가는 용기가 필요합니다. 최대 10문제까지 건너뛰어도 안정적인 등급을 받을 수 있음을 인지해야 합니다.\n*   **선택지 분석 훈련**: 선택지를 읽을 때 통으로 판단하지 말고, 의미 단위로 짧게 끊어서(슬래시(/)) 각 부분이 지문과 일치하는지 단계적으로 확인하는 연습을 해야 합니다.\n*   **배경지식 활용**: \'보기\'의 추상적인 설명을 이해할 때, 자신이 이미 학습한 작품(예: 광장, 봄길)을 \'모델\' 또는 \'샘플\'로 삼아 구체적으로 이해하려는 노력이 필요합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_014', 'lesson_note', '중요 노트', '조창훈', '*   모의고사의 점수 자체보다, 시험을 치르는 과정에서 자신의 문제점을 발견하고 전략을 수정하는 것이 더 중요합니다.\n*   수능 전까지 다양한 장르의 글(수필, 화법과 작문, 매체 등)을 꾸준히 읽어두어야 시험장에서 빠르고 정확한 독해가 가능합니다.\n*   강사나 유튜버가 말하는 \'정독\'은 모든 지문에 해당하는 것이 아니며, 시간 내에 풀기 위해서는 강약 조절과 전략적 독해가 필수적입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_015', 'lesson_note', '핵심 요약', '조창훈', '*   실패를 두려워 말고, 80분 동안 시험을 완주하며 위기관리 능력을 길러야 합니다.\n*   모든 문제를 풀려고 하기보다, 풀 수 있는 문제를 확실히 맞히는 \'선택과 집중\' 전략이 중요합니다.\n*   복잡한 문제는 조건별로 분해하여 단계적으로 접근하는 \'레이어링\' 습관을 들여야 합니다.\n*   출제 오류에 가까운 문제는 시간 낭비를 막기 위해 과감히 건너뛸 줄 알아야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_016', 'lesson_note', '다음 단계', '조창훈', '*   다음 수업 시간에는 학생들이 요청한 EBS 수능특강의 **도파민 관련 독서 지문**을 다루기로 계획했습니다.\n\n\n# 문학 작품 \'찬밥\' 심층 분석 및 서술형 시험 대비 전략 회의');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_017', 'lesson_note', '수업 개요', '조창훈', '본 수업에서는 문정희 시인의 \'찬밥\'이라는 작품을 심층적으로 분석하고, 다가오는 시험의 서술형 문제에 효과적으로 대비하기 위한 전략을 논의했습니다. 또한, 수업 자료 배부 문제 해결 및 과제 제출 방식에 대한 안내가 이루어졌습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_018', 'lesson_note', '주요 논의 내용', '조창훈', '*   **자료 배부 문제:** 일부 학생들이 지난주에 배부된 두꺼운 자료집을 받지 못한 상황이 파악되었습니다. 해당 학생들은 데스크에 문의하여 자료를 수령하도록 안내받았습니다.\n*   **문학 작품 \'찬밥\' 분석:** 작품의 화자, 주요 이미지(촉각적 심상 대비), 주제(어머니의 희생과 사랑), 표현 기법(도치법), 그리고 \'찬밥\'이라는 소재가 갖는 매개체적 의미에 대해 상세히 분석했습니다.\n*   **시험 대비 전략:** 여러 작품을 비교하는 문제(가, 나, 다...)를 효율적으로 푸는 방법과, 선택지에서 자주 사용되는 함정 패턴(\'했냐 안 했냐 패턴\')에 대해 학습했습니다.\n*   **서술형 답안 작성법:** 학교 시험의 서술형 문제가 글자 수 요구량이 많고 까다롭다는 점을 강조하며, 문제의 조건을 번호로 나누어 분석하고 답안을 구조적으로 작성하는 방법을 지도했습니다.\n*   **과제 제출 및 소통:** 과제 제출 시 카테고리 구분의 어려움에 대해 논의하고, 페이지 수를 기준으로 확인할 것이므로 편하게 올리라는 지침이 내려졌습니다. 또한, 시험 범위나 요청 사항은 반드시 톡방을 통해 공유해달라고 강조했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_019', 'lesson_note', '문학 작품 분석: 문정희의 \'찬밥\'', '조창훈', '*   **핵심 주제:** \'찬밥\'이라는 매개체를 통해 과거 어머니의 희생과 사랑을 회상하고, 화자 자신 또한 세상에 헌신하는 존재(\'세상의 찬밥\')가 되겠다고 다짐하는 과정을 다룹니다.\n*   **주요 이미지 및 표현:**\n    *   **촉각적 심상 대비:** \'찬밥\'(차가움, 고난)과 \'따스한 밥\'(따뜻함, 사랑)의 대립을 통해 주제를 효과적으로 부각합니다.\n    *   **매개체로서의 \'찬밥\':** 화자가 어머니의 사랑과 희생을 떠올리게 하는 회상의 핵심 매개체 역할을 합니다.\n    *   **화자의 변화:** 1연에서는 아픈 몸으로 혼자 찬밥을 먹는 \'나\'가, 마지막 연에서는 어머니처럼 헌신하겠다고 다짐하는 성찰적 존재로 변화합니다.\n    *   **깨달음의 확장:** \'찬밥을 먹는\' 개인적 체험이 \'어머니의 사랑은 위대하다\'는 보편적 깨달음으로 확장됩니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_020', 'lesson_note', '시험 대비 전략 및 서술형 문제 풀이법', '조창훈', '*   **서술형 문제 접근법:**\n    1.  문제를 받으면 즉시 작성하지 말고, 요구하는 **조건을 분석하여 번호**를 매깁니다. (예: 1. A에 대해 서술, 2. B와 비교하여 서술)\n    2.  번호를 매긴 조건에 맞춰 작성할 핵심 내용을 먼저 구상한 후 답안 작성을 시작합니다.\n    3.  학교 서술형은 글자 수 요구량이 많으므로, 미리 구조를 잡지 않으면 시간이 부족하거나 논점에서 벗어날 수 있습니다.\n*   **선택지 문제 풀이 전략:**\n    *   **\'했냐 안 했냐 패턴\' 주의:** 지문에서 가정, 상상, 비유로 제시된 내용을 선택지에서 \'실제로 일어난 일\'처럼 서술하는 함정 패턴에 유의해야 합니다.\n    *   **선택지 쪼개기:** 여러 작품(가, 나, 다...)을 비교하는 문제에서는 한 작품을 기준으로 먼저 선택지를 판단하여 시간을 절약하고 소거법을 활용합니다.\n    *   **섣부른 판단 금지:** 확신이 없는 선택지는 바로 틀렸다고 표시하지 말고, 남겨두어 검토 과정에서 실수를 줄이는 것이 중요합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_021', 'lesson_note', '주요 결정 사항', '조창훈', '*   **과제 제출:** 과제는 사진을 찍어 온라인 사이트에 제출합니다. 카테고리 구분이 어려울 경우, **어느 곳에든 올려도 무방**하며 강사가 페이지 수를 직접 확인할 것입니다.\n*   **수업 내용 요청:** 학생들이 듣고 싶은 특정 작품이 있다면 **미리 신청**해야 합니다. 신청이 없으면 강사가 임의로 주제를 선정하여 수업을 진행합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_022', 'lesson_note', '과제 및 다음 단계', '조창훈', '*   **시중 과제 완료:** 배부된 시중 자료 문제집을 계속 풀고, **사진을 찍어 제출 사이트에 꾸준히 업로드**해야 합니다.\n*   **구체적인 질문:** 어려운 문제는 단순히 \'어렵다\'고 하기보다, **어떤 부분이 왜 어려운지 구체적으로 질문**을 올려야 도움을 받을 수 있습니다.\n*   **시험 범위 공유:** 춘향전, 어부사시사 등 시험 범위에 포함될 가능성이 있는 작품들은 **톡방에 공유**하여 강사가 수업 준비에 참고할 수 있도록 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_023', 'lesson_note', '향후 계획', '조창훈', '*   **내신 대비 모의고사:** 시험 범위가 확정되는 대로 **다다음 주부터 내신 대비 모의고사를 지속적으로 실시**할 예정입니다.\n*   **기출 문제 분석:** 추후 작년 기출 시험지를 제공하고, 이를 기반으로 한 서술형 문제 풀이 연습을 심도 있게 진행할 계획입니다.\n*   **선택지 패턴 강의:** \'했냐 안 했냐 패턴\'과 같은 주요 선택지 함정 유형에 대해 다음 주 또는 다다음 주에 다시 한번 정리하는 시간을 가질 것입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_024', 'lesson_note', '중요 공지사항', '조창훈', '*   **자료 수령:** 지난주에 배부된 **두꺼운 자료집을 받지 못한 학생**은 수업 후 데스크에 즉시 알려 반드시 수령해야 합니다.\n*   **수업 작품 선정:** 수강생들의 별도 요청이 없어 이번 수업은 강사가 임의로 작품을 선정했습니다. 듣고 싶은 작품이 있다면 적극적으로 신청해야 합니다.\n*   **공식 소통 채널:** 시험 범위나 요청 사항 등 중요한 내용은 수업 중 구두로 전달하면 강사가 잊을 수 있으므로, 반드시 **\'톡방\'을 통해 기록을 남겨야 합니다**.\n\n# 고전 소설 \'옥주호연\' 및 현대 소설 \'델러웨이의 창\' 심층 분석 및 모의고사 문제 풀이 전략 강의');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_025', 'lesson_note', '수업 개요', '조창훈', '본 수업은 고전 소설 \'옥주호연\'과 현대 소설 \'델러웨이의 창\' 두 작품에 대한 심층적인 분석을 제공합니다. 작품의 핵심 주제와 구조를 파악하는 방법론을 설명하고, 이를 바탕으로 실제 모의고사 문제를 효과적으로 해결하기 위한 구체적인 전략과 접근법을 논의했습니다. 특히, 시간 관리, 문제 유형별 공략법, 선택지 분석 기술 등 실전적인 시험 대비 능력을 향상시키는 데 중점을 두었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_026', 'lesson_note', '주요 학습 내용', '조창훈', '- **작품 분석 방법론**: \'보기\'와 \'중략 줄거리\'를 활용하여 전체 서사를 예측하고, 인물 간의 관계와 핵심 모티프를 파악하는 방법을 학습했습니다.\n- **고전 소설 \'옥주호연\'**: 남장 모티프를 통해 가부장적 사회의 제약을 극복하고 주체성을 실현하는 여성 주인공들의 서사를 분석했습니다.\n- **현대 소설 \'델러웨이의 창\'**: \'시뮬라시옹\'과 \'시뮬라크르\' 개념을 적용하여, 실재하지 않는 가상이 현실을 지배하는 현대 사회의 모습을 비판적으로 탐구했습니다.\n- **모의고사 문제 풀이 전략**: 문제를 \'잡몹\'과 \'보스\'로 비유하여 시간 분배의 중요성을 강조하고, 복잡한 문제를 여러 \'레이어\'로 나누어 단계적으로 해결하는 접근법을 제시했습니다.\n- **선택지 분석 기술**: 긴 선택지를 내용과 해석 부분으로 나누어 분석하고, 핵심 서술어에 집중하여 정오를 빠르고 정확하게 판단하는 훈련법을 공유했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_027', 'lesson_note', '고전 소설 \'옥주호연\' 분석', '조창훈', '### 작품 접근법\n- **\'보기\' 활용**: 작품을 읽기 전 \'보기\'를 통해 \'가부장적 사회\', \'여성 주인공\', \'남장 모티프\', \'공적 영역 진출\' 등의 핵심 키워드를 미리 파악하여 작품의 주제와 갈등 구조를 예측합니다.\n- **\'중략 부분 줄거리\' 활용**: 세 자매가 집을 떠나 최환 삼형제를 만나고, 함께 공을 세워 높은 벼슬을 얻었다는 정보를 통해 중략 전후의 내용을 추론합니다. (전: 가출 동기, 후: 정체 발각 및 인정)\n\n### 핵심 내용 분석\n- **갈등의 원인**: 유생(아버지)이 이웃의 아들들이 과거에 급제한 것을 부러워하며 딸만 셋인 자신의 처지를 한탄합니다. 시녀 춘행이 딸들이 몰래 무예를 익히는 것을 고자질하자, 유생은 술김에 가문의 망신이라며 딸을 죽이려 합니다.\n- **가출 결심**: 세 자매(벽주, 자주, 명주)는 아버지가 자식을 죽이는 죄를 짓게 하지 않기 위해, 스스로 집을 떠나 공명을 이루고 돌아오기로 결심합니다.\n- **정체 발각과 인정**: 황제는 세 자매가 여자임을 이미 알고 있었고, 연회에서 일부러 옷을 벗고 연못에 들어가라는 짓궂은 명령을 내립니다. 이를 통해 세 자매의 정체를 신하들 앞에서 자연스럽게 밝히고, 그들이 세운 큰 공을 인정하며 칭찬합니다. 이는 정체가 밝혀진 후에도 공을 인정받는다는 \'보기\'의 내용과 일치합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_028', 'lesson_note', '현대 소설 \'델러웨이의 창\' 분석', '조창훈', '### 작품 접근법\n- **\'보기\' 활용**: 현대 사회학자 장 보드리야르의 \'시뮬라시옹(Simulation)\'과 \'시뮬라크르(Simulacrum)\' 개념을 통해 작품을 이해합니다. \'델러웨이\'가 실존하지 않는 대상을 실제처럼 만든 결과물, 즉 \'시뮬라크르\'일 것이라고 미리 추측하고 작품을 읽습니다.\n\n### 핵심 내용 분석\n- **\'델러웨이\'의 탄생**: \'사내\'라는 인물이 \'델러웨이\'라는 가상의 사진작가를 창조합니다. 이는 실제가 아닌 것을 실제처럼 만드는 과정인 \'시뮬라시옹\'에 해당합니다.\n- **\'델러웨이 신드롬\'**: \'사내\'가 퍼뜨린 이야기에 대중, 비평가, 아카데미 원장까지 열광하며 \'델러웨이\'와 그의 기법을 연구하고 토론합니다. 실체가 없는 \'델러웨이\'는 독자적인 생명력을 얻은 \'시뮬라크르\'가 됩니다.\n- **진실 추적**: 주인공 \'나\'는 델로웨이에 대한 모든 정보의 출처가 \'사내\' 한 명이라는 사실에 의문을 품습니다. 결국 아카데미 원장과의 대화를 통해 \'델러웨이\'를 처음 언급한 수강생이 바로 \'사내\'였음을 확인하며 진실에 도달합니다.\n- **주제**: 실제보다 더 실제 같은 가짜(시뮬라크르)에 열광하며 진실과 거짓의 경계가 무너진 현대 사회의 모습을 풍자하고 비판합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_029', 'lesson_note', '모의고사 문제 풀이 전략', '조창훈', '- **게임 비유를 통한 시간 관리**: 시험의 문제들을 쉬운 \'잡몹\'과 어려운 \'보스\'로 구분합니다. \'잡몹\' 문제에서 시간을 최대한 절약하고 점수를 확보해야, \'보스\' 문제에 시간적 여유를 가지고 도전하거나 전략적으로 포기할 수 있습니다.\n- **\'레이어(Layer)\' 접근법**: 한 번에 답을 찾으려 하지 말고, 문제를 여러 층위로 나누어 단계적으로 해결합니다. \n    1.  **1단계**: 선택지의 내용과 해석이 서로 논리적으로 연결되는지 확인합니다. (좌우 매칭)\n    2.  **2단계**: 선택지에 제시된 본문 내용이 정확한지 확인합니다.\n    3.  **3단계**: \'보기\'의 해석과 선택지의 해석이 일치하는지 최종적으로 점검합니다.\n- **선택지 해체 및 분석**: 긴 선택지는 핵심 요소를 분리하여 분석합니다. 특히 인물, 행위, 서술어에 집중하여 줄을 치며 핵심 조각을 찾아 본문과 대조하는 연습이 중요합니다.\n- **적극적인 읽기**: 눈으로만 읽지 말고, 중요한 인물이나 서술어에 표시하며 능동적으로 정보를 처리해야 실수를 줄일 수 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_030', 'lesson_note', '주요 용어 해설', '조창훈', '- **화소(모티프)**: 이야기의 재료가 되는 작은 단위. (예: 남장 모티프)\n- **생(生)**: 고전 소설에서 과거에 급제하기 전의 남성을 높여 부르는 말. (예: 허생, 이생 -> 미스터 허, 미스터 이)\n- **서술자의 개입 (편집자적 논평)**: 서술자가 작품에 직접 개입하여 인물이나 사건에 대해 평가하거나 자신의 감정을 드러내는 것. 주로 전지적 작가 시점에서 나타납니다.\n- **시뮬라시옹(Simulation)**: 실재하지 않는 대상을 실재하는 것처럼 보이게 만드는 과정.\n- **시뮬라크르(Simulacrum)**: 시뮬라시옹을 통해 만들어진, 원본 없는 복제물. 실제보다 더 실제같이 여겨지기도 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_031', 'lesson_note', '강사의 강조 사항', '조창훈', '- **적극적 문제 풀이 습관**: 눈으로만 푸는 습관을 버리고, 문제와 선택지의 핵심 요소에 직접 표시하고 분석하는 습관을 들여야 합니다.\n- **모의고사의 중요성**: 모의고사는 점수 확인뿐만 아니라, 시간 관리, 위기 상황 대처 등 실전 운영 능력을 연습하는 중요한 기회이므로 매번 진지하게 임해야 합니다.\n- **사고 과정 훈련**: 정답을 맞히는 것뿐만 아니라, 문제를 어떻게 분석하고 어떤 순서로 사고하여 답에 도달했는지 복기하는 과정이 중요합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_032', 'lesson_note', '학생 질문 및 답변', '조창훈', '- **질문**: \'옥주호연\' 문제에서 \'최완과 자주는 모두 절강 사람으로 알려져 있다\'는 선택지가 왜 맞는지에 대한 질문.\n- **답변**: 해당 내용은 황제의 대사에서 나온 정보로, 작품 속 인물(황제)이 그렇게 알고 있음을 보여줍니다. 선택지의 \'알려져 있다\'는 작품 밖의 독자가 아닌 작품 속 세계에서의 인식을 의미하므로 타당합니다.\n- **질문**: 여자가 무예를 훈련하는 것이 왜 죽을죄가 되는지에 대한 질문.\n- **답변**: 작품이 창작된 시대의 가치관(남존여비 등)이 반영된 설정으로, 역사적 고증보다는 해당 작품의 \'세계관\'으로 받아들이고 이해해야 합니다.\n\n# 김소월 시 심층 분석 강의: 진달래꽃, 초혼, 산유화, 접동새, 가는 길');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_033', 'lesson_note', '수업 개요', '조창훈', '본 수업은 학교 내신 시험 대비를 위해 김소월 시인의 주요 작품 5편(진달래꽃, 초혼, 산유화, 접동새, 가는 길)에 대한 심층 분석을 진행했습니다. 교과 과정에서 다루지 않았을 가능성이 높은 작품들을 중심으로, 각 시의 성격, 주제, 표현법, 구절의 의미를 상세히 학습하고 관련 문학 용어를 정리하여 시험에 완벽히 대비하는 것을 목표로 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_034', 'lesson_note', '주요 학습 내용', '조창훈', '- **김소월 시의 공통적 특징**: 민요적 율격(3음보, 7·5조), 전통적 정서(한), 애상적 분위기 등을 중심으로 김소월 시의 전반적인 특징을 파악했습니다.\n- **작품별 심층 분석**: 5개 작품의 핵심 내용, 구절별 의미, 사용된 문학 기법을 상세히 분석했습니다.\n  - **진달래꽃**: 이별의 정한과 승화, 반어법, 역설법\n  - **초혼**: 사별의 한과 격정적 어조, 고복의식 모티프\n  - **산유화**: 존재의 근원적 고독과 관조적 태도, 자연의 섭리\n  - **접동새**: 혈육의 한과 설화 모티프\n  - **가는 길**: 이별의 망설임과 미련, 시행 배열을 통한 호흡 조절\n- **주요 문학 용어 정리**: 반어법과 역설법의 차이, 관조적 태도, 감정이입, 애이불비 등 시험에 자주 출제되는 핵심 문학 용어의 개념을 명확히 했습니다.\n- **실전 문제 풀이**: 각 작품에 대한 OX 문제를 풀며 학습 내용을 점검하고, 문제 풀이 전략(선택지 분석 방법)을 익혔습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_035', 'lesson_note', '김소월 시 공통 특징 분석', '조창훈', '- **민요적 율격**: 대부분의 시에서 3음보 율격과 7·5조 음수율이 공통적으로 나타나며, 이는 민요적이고 전통적인 느낌을 형성합니다.\n- **전통적 정서**: \'한(恨)\'이라는 한국 고유의 정서를 중심으로 이별, 사별, 혈육의 정 등 다양한 주제를 다룹니다.\n- **애상적 어조**: 전반적으로 슬픔과 그리움의 정서가 짙게 깔린 애상적인 분위기를 자아냅니다.\n- **향토성**: \'영변의 약산\', \'진두강\' 등 구체적인 지명을 사용하여 향토적인 분위기와 현장감을 부여합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_036', 'lesson_note', '작품별 심층 분석', '조창훈', '### 진달래꽃\n- **주제**: 이별의 정한과 그 슬픔의 초극(승화)\n- **특징**: \n  - **반어법**: \'죽어도 아니 눈물 흘리오리다\' 부분에서 속마음과 반대로 표현하여 슬픔을 강조합니다. (애이불비: 슬프지만 겉으로 슬픔을 드러내지 않음)\n  - **역설법**: \'사뿐히 즈려밟고 가시옵소서\'에서 모순된 표현을 통해 헌신적 사랑과 희생을 강조합니다.\n  - **산화공덕**: 떠나는 임의 앞길을 축복하는 불교적 모티프를 차용하여 이별의 슬픔을 축복으로 승화시킵니다.\n  - **수미상관**: 1연과 4연의 구조적 유사성을 통해 형태적 안정감과 주제를 강조합니다.\n\n### 초혼\n- **주제**: 임의 죽음으로 인한 슬픔과 한(사별의 한)\n- **특징**:\n  - **고복 의식**: 죽은 이의 이름을 부르는 전통 장례 의식 \'초혼\'을 모티프로 사용하여 주제를 명확히 합니다.\n  - **격정적·직설적 어조**: \'산산이 부서진 이름이여!\', \'부르다가 내가 죽을 이름이여!\' 등 감정을 직접적으로 표출하며 슬픔을 극대화합니다.\n  - **점층법**: 감정이 점차 고조되는 방식으로 시상을 전개하여 슬픔의 깊이를 더합니다.\n  - **감정이입**: \'사슴의 무리도 슬피 운다\'에서 화자의 슬픔을 사슴에 투영합니다.\n\n### 산유화\n- **주제**: 모든 존재가 지닌 근원적 고독과 대자연의 섭리(생성과 소멸)\n- **특징**:\n  - **관조적 태도**: 대상을 멀리서(저만치) 바라보며 감정을 절제하는 태도를 보입니다. 이는 격정적인 다른 시들과 차이를 보입니다.\n  - **자연의 섭리**: \'꽃이 피네\' (생성)와 \'꽃이 지네\' (소멸)의 반복을 통해 순환하는 자연의 질서를 보여줍니다.\n  - **시적 허용**: \'갈\' (가을)과 같이 운율을 위해 의도적으로 변형된 시어를 사용합니다.\n  - **감정이입**: \'산에서 우는 작은 새\'에 화자의 고독한 감정을 이입합니다.\n\n### 접동새\n- **주제**: 죽은 누이가 동생들을 그리워하는 혈육의 한\n- **특징**:\n  - **설화 모티프**: 계모에게 핍박받다 죽어 접동새가 된 누나의 설화를 바탕으로 시상을 전개합니다.\n  - **감정이입**: \'접동새\'는 누나의 억울한 한이 투영된 존재이자 화신입니다.\n  - **청각적 심상**: \'접동 접동 아우래비 접동\' 등 새의 울음소리를 흉내 낸 의성어를 사용하여 애상적인 분위기를 고조시킵니다.\n  - **향토성**: \'진두강\'이라는 구체적 지명을 통해 사실감을 부여합니다.\n\n### 가는 길\n- **주제**: 임과의 이별에 대한 아쉬움과 망설임\n- **특징**:\n  - **시행 배열을 통한 호흡 조절**: \n    - 1~2연: \'그립다 / 말을 할까 / 하니 그리워\' 와 같이 한 행에 1음보씩 짧게 배열하여 망설임과 주저함(느린 호흡)을 시각적으로 표현합니다.\n    - 3~4연: \'저 산에도 까마귀 들에 까마귀\' 와 같이 한 행에 3음보를 모두 배열하여 재촉하는 듯한 느낌과 상황의 촉박함(빠른 호흡)을 나타냅니다.\n  - **객관적 상관물**: \'까마귀\'와 \'흐르는 물\'은 화자의 망설이는 마음과 대조적으로, 떠나기를 재촉하며 안타까움을 고조시키는 역할을 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_037', 'lesson_note', '주요 문학 용어 정리', '조창훈', '- **슬픔의 종류**: \n  - **애상(哀傷)**: 잔잔하고 쓸쓸한 슬픔.\n  - **비통(悲痛)**: 가슴이 찢어질 듯한 격렬한 슬픔.\n  - **비장(悲壯)**: 큰 뜻과 관련된 장엄함이 깃든 슬픔.\n- **반어법(Irony)**: 표현과 실제 상황/속마음이 반대되는 경우. 슬픈 상황에서 \'울지 않겠다\'고 말하는 것.\n- **역설법(Paradox)**: 표현 자체에 논리적 모순이 있지만 그 속에 진리를 담고 있는 경우. \'사뿐히 즈려밟고\' 처럼 양립 불가능한 행위를 결합한 표현.\n- **관조적(Contemplative) 태도**: 감정적으로 개입하지 않고 대상을 거리를 두고 차분히 바라보는 태도. 종종 깨달음으로 이어진다.\n- **감정이입(Empathy)**: 화자의 감정을 자연물 등 다른 대상에 투영하여 표현하는 것. \'사슴이 슬피 운다\' 등.\n- **애이불비(哀而不悲)**: 속으로는 슬프지만 겉으로는 슬픔을 드러내지 않는 태도. 인내와 극복 의지를 내포.\n- **무상함(Transience)**: 영원한 것은 없다는 허무함이나 덧없음의 정서.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_038', 'lesson_note', '수업 중 Q&A 및 토론', '조창훈', '- **질문**: 수미상관은 내용이 완전히 똑같아야 하나요?\n  - **답변**: 완벽히 똑같지 않아도 됩니다. 일부 변형된 형태의 \'변형된 수미상관\'도 수미상관으로 인정됩니다.\n\n- **질문**: \'여성적 어조\' 같은 표현이 요즘도 시험에 나오나요?\n  - **답변**: 해설서에는 여전히 등장하지만, 현대적 관점에서 성별에 따른 고정관념을 줄 수 있어 출제 빈도가 낮아지는 추세입니다. 하지만 학습서에 명시된 내용은 알아두어야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_039', 'lesson_note', '과제 및 다음 활동', '조창훈', '- **수업 자료 복습**: 오늘 배운 김소월 시 5편의 분석 내용을 다시 한번 꼼꼼히 읽고 정리합니다.\n- **OX 문제 풀이**: 학습지 뒷부분의 \'실전 대비 OX 문제\'를 모두 풀어옵니다. (진달래꽃, 초혼, 산유화, 접동새, 가는 길 각 5문제씩)\n- **한용운 시 예습**: 학습지에 포함된 한용운 시인의 작품들은 스스로 학습하고 질문이 있으면 제출합니다.\n- **추가 자료 학습**: 이번 주에 추가로 배부될 시중 자료(문학 아카데미, 족보닷컴 등)를 과제로 풀어옵니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_040', 'lesson_note', '선생님의 요약 및 결론', '조창훈', '- **문제 풀이 전략**: 시험 문제를 풀 때, 특히 OX 문제에서는 선택지를 의미 단위로 잘게 쪼개어(예: \'3음보 율격\', \'규칙적\', \'민요적\') 각 부분이 모두 맞는지 개별적으로 판단하는 연습이 중요합니다. \n- **패턴 파악**: \'가정\'을 \'실제 겪은 일\'처럼 서술하는 함정(했냐 안 했냐 패턴) 등 내신 시험에 자주 나오는 선택지 패턴을 익혀두면 실수를 줄일 수 있습니다.\n- **꾸준한 학습**: 시는 기본 지식을 갖추는 것도 중요하지만, 이를 바탕으로 실전에서 적용하는 기술을 익히는 것이 핵심입니다. 과제를 꾸준히 수행하며 학습 내용을 자신의 것으로 만들어야 합니다.\n\n# 3월 모의고사 국어 비문학 문제 풀이 전략 강의: 게임 공략법을 활용한 지문 분석 및 문제 해결 방법론');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_041', 'lesson_note', '강의 개요', '조창훈', '본 강의는 3월 모의고사 국어 영역, 특히 비문학 파트의 효과적인 문제 풀이 전략을 다룹니다. 강사는 시험을 RPG 게임에 비유하여, 문제 유형을 \'잡몹\'과 \'보스\'로 구분하고 각기 다른 접근법을 취해야 한다고 강조합니다. 지문 독해 시에는 정보를 잘게 나누어 단계적으로 분석하는 \'레이어링\' 기법과 핵심 문장 구조(필요조건, 양보절)를 파악하는 방법을 중심으로, 실제 기출문제(11~13번)를 상세히 해설하며 적용법을 제시합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_042', 'lesson_note', '핵심 전략: 시험을 게임처럼 접근하기', '조창훈', '강사는 모의고사를 RPG 게임을 클리어하는 과정에 비유하며 등급별 맞춤 전략을 제시했습니다.\n\n*   **\'잡몹\'과 \'보스\'의 개념**\n    *   **잡몹**: 대부분의 쉬운 문제 (약 35/45문제). 최소한의 시간과 에너지(\'피\')를 소모하여 빠르고 정확하게 해결해야 하는 문제들.\n    *   **보스**: 고난도 킬러 문항. 높은 등급을 가르는 변별력 있는 문제들.\n\n*   **목표 등급별 공략법**\n    *   **1-2등급 목표**: \'잡몹\' 문제에서 절대 힘을 빼면 안 됩니다. 간단하고 신속하게 해결하여 \'보스\' 문제에 도전할 시간과 에너지를 확보해야 합니다.\n    *   **2-3등급 목표**: 모든 \'보스\' 문제를 풀려고 하기보다, 확실하게 잡을 수 있는 \'잡몹\'을 놓치지 않는 것이 중요합니다. 어려운 \'보스\' 문제는 과감히 건너뛰거나(겐토) 일부만 풀고 넘어가는 전략이 유효합니다. 모든 \'보스\'를 포기해도 나머지 문제만 다 맞히면 충분히 목표 등급을 달성할 수 있습니다.\n\n*   **\'보스\' 문제 접근법**: 한 번의 \'필살기\'로 해결하려 하지 말고, 여러 번의 \'짜잘한 공격\'으로 \'보스\'의 체력(\'피\')을 깎아야 합니다. 즉, 문제의 조건을 하나씩 분석하고 단계적으로 해결해 나가야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_043', 'lesson_note', '비문학 지문 분석 방법론', '조창훈', '복잡한 비문학 지문을 효과적으로 분석하기 위한 구체적인 방법론이 제시되었습니다.\n\n*   **\'돼지 꿀꿀\' 이론**: 길고 복잡한 문장(\'돼지 꿀꿀거리는 소리\')을 통째로 이해하려 하지 말고, 잘게 잘라서 핵심 정보만 추출하는 연습이 필요합니다. 생각과 행동, 미션을 단순하고 반복 가능한 단위로 쪼개는 것이 중요합니다.\n*   **훑어보며 추상화하기**: 지문을 정독하기 전에, 문단별로 빠르게 훑으며 핵심어를 연결하여 전체 구조와 내용의 흐름을 예측합니다. 이 과정을 통해 예측 가능한 상태에서 정독하여 이해도를 높일 수 있습니다.\n*   **레이어 쌓기**: 한 번에 정답을 찾으려 하지 말고, 지문의 조건을 하나씩 확인하며 단계적으로 정보를 쌓아나가는 방식으로 접근해야 합니다. 선택지를 분석할 때도 이 방식을 적용하여 불확실성을 줄여나갑니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_044', 'lesson_note', '법률 지문 독해 심층 분석 (11-13번 지문)', '조창훈', '법률 지문 독해 시 반드시 활용해야 할 핵심 기술들이 강조되었습니다.\n\n*   **핵심 표현 파악**: 법 지문에서는 특정 표현이 문제의 핵심 단서가 됩니다.\n    *   **필요조건**: \'~어야 한다\'와 같은 표현은 반드시 출제되므로 PQ 기호를 사용하여 명확히 분석해야 합니다.\n    *   **양보절**: \'~일지라도\'와 같은 표현은 조건, 인과, 상관관계를 깨는 예외 조항이므로 특히 주의해야 합니다. 책임 소재를 판단하는 중요한 단서가 됩니다.\n*   **시점/시기 정보 처리**: 계약 체결, 이행 완료, 위험 이전 등 시점에 대한 정보가 나올 경우, **수평선**을 그려 시간의 흐름에 따라 각 주체의 책임과 의무가 어떻게 변하는지 시각적으로 정리하면 실수를 줄일 수 있습니다.\n*   **케이스 분류**: \'경우\', \'다면\' 등으로 나열되는 여러 사례(Case)들은 C1, C2, C3 등으로 넘버링하여 각 조건과 결과를 명확히 구분하고 구조화해야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_045', 'lesson_note', '문제 유형별 풀이 전략', '조창훈', '실제 모의고사 문제를 예시로 각 유형에 맞는 구체적인 풀이법을 설명했습니다.\n\n*   **11번 (내용 일치 문제)**: \'잡몹\'에 해당. 선택지의 모든 내용을 확인하기보다, 지문의 핵심 조각(민법, CISG 등)과 선택지를 연결하여 빠르게 판단합니다. 이 문제의 답은 지문의 \'양보절\'과 \'필요조건\'을 반대로 서술한 4번 선택지에서 쉽게 찾을 수 있었습니다.\n*   **12번 (조건 게임/적절성 판단 문제)**: 지문의 특정 부분(기억)에 대한 이해를 묻는 문제. 선택지를 먼저 분석하기보다, 지문의 조건(C1~C4)을 먼저 정리한 후, 각 선택지가 어떤 케이스에 해당하는지 \'치환\'하여 빠르게 오답을 소거합니다. 정답은 \'원유/천연가스\'(C4)의 경우 계약 체결 시점에 위험이 이전될 수 있다는 내용이었습니다.\n*   **13번 (사례 적용 <보기> 문제)**: 오답률이 높은 \'보스\' 문제. **\'링크 앤 치환\'** 전략을 사용합니다.\n    1.  **링크(Link)**: 보기의 사례를 분석하여 지문의 어떤 개념과 케이스(C1)에 해당하는지 연결합니다.\n    2.  **치환(Substitute)**: 보기의 인물(A, B)과 상황을 지문의 용어(매도인, 매수인, 위험 이전 시점)로 모두 바꿉니다.\n    3.  **분석**: 수평선을 활용해 \'위험 이전 시점\'을 명확히 파악하고, 사건(훼손)이 그 전후 어디에서 발생했는지 판단합니다. 이 문제의 핵심은 \'최초 운송인에게 인도된 시점\'에 이미 위험이 이전되었음을 파악하는 것이었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_046', 'lesson_note', '강사의 핵심 강조 사항', '조창훈', '강사는 올바른 문제 풀이 습관의 중요성을 반복적으로 강조했습니다.\n\n*   **눈으로만 풀지 말 것**: 안정적인 1등급이 아닌 이상, 눈으로만 읽고 푸는 것은 가장 위험한 습관입니다. 손으로 직접 줄을 치고, 기호를 쓰고, 수평선을 그리는 등 적극적으로 표시하며 풀어야 합니다.\n*   **한 번에 해결하려 하지 말 것**: 어려운 문제일수록 한 번에 답을 내려고 하면 안 됩니다. 문장과 선택지를 잘게 쪼개고, 레이어를 쌓듯이 단계적으로 접근해야 실수가 줄고 정답이 보입니다.\n*   **선택지에 O/X 함부로 치지 말 것**: 확신이 없는 상태에서 섣불리 O/X를 판단하면 사고가 꼬일 수 있습니다. 정답의 근거가 명확해질 때까지 판단을 보류하고 레이어를 쌓는 데 집중해야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_047', 'lesson_note', '주요 학습 포인트', '조창훈', '*   시험 전략의 핵심은 **\'잡몹\'을 빠르고 정확하게 처리**하여 \'보스\'에 도전할 시간과 에너지를 확보하는 것입니다.\n*   비문학 지문 독해는 **\'추상화 -> 구조화 -> 정독\'**의 순서로 진행되어야 합니다.\n*   법률 지문에서는 **필요조건, 양보절, 시점, 케이스 분류**가 핵심 분석 도구입니다.\n*   <보기> 문제의 정복 비결은 보기의 정보를 지문의 개념으로 완벽하게 **\'링크 앤 치환\'**하는 능력에 있습니다.\n*   가장 중요한 것은 \'한 방\'을 노리는 것이 아니라, **\'잘게 쪼개고, 겹겹이 쌓아가는\'** 문제 풀이 습관을 체화하는 것입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_048', 'lesson_note', '다음 학습 안내', '조창훈', '다음 시간에는 이어서 문학 파트의 김소월, 한용운 작품 해설을 진행할 예정입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_049', 'lesson_note', '강의 개요', '조창훈', '본 강의는 중세 국어의 주요 음운, 특히 현대 국어에서 사라진 반치음(ㅿ), 순경음 비읍(ㅸ), 옛이응(ㆁ), 아래아(ㆍ)에 대해 심도 있게 다루었습니다. 각 음운의 음가와 특징, 시대에 따른 변천 과정, 그리고 이러한 변화가 현대 국어의 불규칙 활용, 장음, 방언 등에 어떤 흔적을 남겼는지 상세히 설명했습니다. 더불어 성조(방점)와 어두자음군에 대한 분석도 포함되었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_050', 'lesson_note', '주요 음운 심층 분석', '조창훈', '### 반치음 (ㅿ)\n\n* **특징**: 잇소리(치음), 울림소리로 15세기에 사용되다 소실되었습니다.\n* **변천 과정**:\n  * **단순 소실**: `사지` > `사이`, `마잠` > `마암` > `마음`의 과정에서 `ㅿ`이 탈락했습니다.\n  * **시옷(ㅅ)으로 강화**: `한즈음` > `한숨`, `몸조` > `몸소`와 같이 `ㅅ`으로 바뀌는 경우도 있었습니다.\n* **현대 국어와의 연관성**: `ㅅ` 불규칙 활용의 기원이 됩니다.\n  * **중세**: 어간 `젖-`은 모음 어미 앞에서 `저ᅀᅥ`(저저)로, 자음 어미 앞에서 `젓고`로 실현되는 음운론적 이형태였습니다.\n  * **현대**: 반치음이 소실되면서, 모음 어미 앞에서 `ㅅ`이 탈락하는 `ㅅ` 불규칙 활용(`젓다` → `저어`)으로 굳어졌습니다.\n\n### 순경음 비읍 (ㅸ)\n\n* **특징**: 입술소리, 유성 양순 마찰음(영어 \'v\'와 유사)으로, 주로 모음 사이에서 나타났으며 16세기에 소실되었습니다.\n* **변천 과정**:\n  * `ㅏ/ㅓ` 앞에서는 반모음 \'w\'로 변화: `돕다` + `-아` → `도바` → 현대 `도와`.\n  * `ㆍ`(아래아)나 `ㅡ` 앞에서는 탈락 후 `ㅗ/ㅜ`로 변화: `돕-` + `-안` → `도온` → 현대 `도운`. `셔블`(서울) → `셔울`.\n* **현대 국어와의 연관성**: `ㅂ` 불규칙 활용의 기원이 됩니다.\n  * **중세**: 어간 `돕-`은 모음 어미 앞에서 `도ᄫᅡ`(도바)로, 자음 어미 앞에서 `돕고`로 실현되었습니다.\n  * **현대**: 순경음 비읍이 반모음 \'w\' 또는 `ㅗ/ㅜ`로 바뀌면서 `ㅂ` 불규칙 활용(`돕다` → `도와`, `곱다` → `고와`, `덥다` → `더워`)이 되었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_051', 'lesson_note', '기타 주요 음운 변천', '조창훈', '* **옛이응(ㆁ)**: 종성(받침)에서 [ŋ] 발음을 표기하는 데 사용되었습니다. 현대 국어에서는 종성 \'ㅇ\'이 이 기능을 완전히 계승했으며, 초성 \'ㅇ\'은 예나 지금이나 음가가 없습니다.\n* **아래아(ㆍ)**:\n  * **1단계 소실 (16세기)**: 단어의 둘째 음절 이하에서 \'ㅡ\'로 변화 (`마잠` → `마음`).\n  * **2단계 소실 (18세기)**: 단어의 첫째 음절에서 \'ㅏ\'로 변화 (`마음` → `마음`).\n  * **영향**: 아래아의 소실은 현대 국어의 모음 조화 파괴에 결정적인 영향을 미쳤습니다.\n* **어두자음군**:\n  * 단어의 첫소리에 둘 이상의 자음이 오는 것으로, `ㅂㄷ`, `ㅂㅅㄱ` 등이 있었습니다. (예: `ᄯᅳᆮ` → 뜻, `ᄡᆞᆯ` → 쌀)\n  * 비읍계(`ㅂㄷ`, `ㅂㅅ`)는 각 자음이 모두 발음되었을 것으로 추정됩니다. (예: `브듯`, `브살`)\n  * 시옷계(`ㅅㄱ`, `ㅅㄷ`)는 된소리(`ㄲ`, `ㄸ`)로 발음되었습니다.\n  * 현대 국어에 `좁쌀`, `햅쌀`, `입때` 등의 단어에 그 흔적이 남아있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_052', 'lesson_note', '성조와 방점', '조창훈', '* **정의**: 글자 왼쪽에 점을 찍어 소리의 높낮이(성조)를 표시하는 방법입니다.\n* **종류**:\n  * **평성 (점 없음)**: 낮은 소리\n  * **거성 (점 1개)**: 높은 소리\n  * **상성 (점 2개)**: 낮았다가 높아지는 소리\n* **현대 국어의 흔적**: 상성은 현대 국어의 **장음(긴 소리)**으로 변화했습니다. (예: `말`[言]은 상성, `말`[馬]은 거성)\n* **방언**: 부산 사투리 등 일부 방언에는 성조의 흔적이 뚜렷이 남아있어 `눈`(眼)과 `눈`(雪)의 억양이 다르게 발음됩니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_053', 'lesson_note', '현대 국어와의 연관성 요약', '조창훈', '* **불규칙 활용**: `ㅅ 불규칙`(예: `짓다`→`지어`)과 `ㅂ 불규칙`(예: `덥다`→`더워`)은 각각 중세 국어의 `반치음(ㅿ)`과 `순경음 비읍(ㅸ)`의 소실 과정에서 비롯되었습니다.\n* **장단음**: 현대 국어의 장음(긴 소리)은 중세 국어의 `상성`에서 유래했습니다.\n* **어두자음군 흔적**: `좁쌀`, `입때`와 같은 단어에서 `ㅂ` 받침의 형태로 그 흔적을 찾을 수 있습니다.\n* **방언의 성조**: 부산 사투리의 억양은 중세 국어의 성조 체계를 일부 유지하고 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_054', 'lesson_note', '강의 자료 관련 특이사항', '조창훈', '* **자료 출처**: 강의에 사용된 프린트는 과거 신도고등학교 교사가 만든 자료로, 정리가 매우 잘 되어 있어 강사가 수년째 활용하고 있다고 밝혔습니다.\n* **오류 지적**:\n  * 모음 조화 파괴의 예시로 든 `없삽기로`는 부적절한 예시라고 지적했습니다.\n  * 순경음 비읍 파트의 `셔발`은 `셔블`의 오타임을 명확히 했습니다. (`셔`가 음성 모음이므로 뒤따르는 모음도 `ㅡ`가 되어야 함)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_055', 'lesson_note', '핵심 학습 전략', '조창훈', '* **불규칙 활용 판별**: 동사의 규칙/불규칙 활용 여부를 판단할 때는 습관적으로 어간에 **`아/어`**를 붙여서 변화를 확인하는 것이 중요합니다.\n* **문제 해결적 학습**: 개념을 공부할 때, 해당 내용이 어떤 유형의 문제로 출제될 수 있을지 상상하며 학습하는 자세가 필요하다고 강조했습니다.\n* **변천 순서 이해**: `순경음 비읍 소실`이 `모음 조화 파괴(아래아 변천)`보다 먼저 일어났다는 시간적 순서를 이해하는 것이 음운 변화를 파악하는 데 중요합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_056', 'lesson_note', 'Q&A 및 토의', '조창훈', '* 강사는 부산 사투리의 성조를 설명하기 위해 수강생들에게 \'블루베리 스무디\', \'눈이 아파/눈이 내리다\' 등의 발음을 유도하며 현대 방언에 남아있는 중세 국어의 흔적을 체험적으로 이해시켰습니다.\n\n# 3월 고3 모의고사 \'언어와 매체\' 심층 분석 및 문제 풀이 전략 강의');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_057', 'lesson_note', '강의 개요', '조창훈', '3월 고3 모의고사 \'언어와 매체\' 영역에 대한 심층 해설 강의입니다. 주요 문항(35-39번, 45번)을 중심으로, 학생들이 어려워했던 개념을 설명하고 실전적인 문제 풀이 전략을 제시했습니다. 특히, 쉬운 문제와 어려운 문제를 구분하여 대처하는 \'잡몹/보스\' 전략과 복잡한 문제를 단계적으로 분석하는 \'레이어 쌓기\' 접근법을 강조했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_058', 'lesson_note', '주요 분석 문제', '조창훈', '• **35-36번:** 문장 구조의 중의성\n• **37번:** 음운 변동 규칙 적용\n• **38번:** 중세 국어의 사동 접미사\n• **39번:** 합성어의 구조 분석 (통사적/비통사적 합성)\n• **45번:** 누리 소통망(SNS) 대화 기반의 매체 정보 변경 분석');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_059', 'lesson_note', '핵심 개념 정리', '조창훈', '• **문장 구조와 중의성:** 수식어(관형어, 부사어)의 수식 범위, 접속 조사(\'와/과\', \'랑\', \'하고\')와 부사격 조사의 기능적 구분, 문장의 주체 해석 차이로 인해 발생하는 중의성을 다룹니다.\n• **음운 변동:** 음절 끝소리 규칙, 비음화, 유음화, 경음화, ㄴ첨가 등 기본적인 음운 변동 규칙을 복습하고 예시에 적용했습니다.\n• **사동 표현:** 현대 국어의 사동 접미사(\'이히리기우구추\')와 중세 국어의 사동 접미사(\'이히리기\', \'아/으\')를 비교하며, 차이점(\'아/으\')이 출제 포인트임을 설명했습니다.\n• **합성어 분석:** 직접 구성 성분 분석을 통해 합성어를 판별하고, 어미(\'아/어/고\', \'은/ㄴ/을/ㄹ\')의 포함 여부에 따라 통사적 합성어를 구분하는 방법을 다룹니다. 특히 \'길짐승\'과 \'날짐승\'의 사례를 통해 심층적인 형태소 분석의 중요성을 강조했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_060', 'lesson_note', '문제 풀이 전략 및 조언', '조창훈', '• **\'잡몹\'과 \'보스\' 구분:** 37, 38번과 같이 쉽게 풀 수 있는 문제(\'잡몹\')에서 시간과 정신적 에너지를 아껴, 39번과 같은 고난도 문제(\'보스\')에 집중해야 합니다. 모든 문제를 맞히려 하기보다 아는 것을 확실히 맞히는 시험 운영 능력이 중요합니다.\n• **\'레이어 쌓기\' 접근법:** 45번 문제처럼 정보가 복잡하게 얽힌 경우, 문제의 요구사항과 선택지를 여러 개의 작은 단위(예: 의견 반영 주체, 목적, 변경 결과)로 나누어 단계적으로 검증해야 합니다. 이를 통해 실수를 줄이고 정답률을 높일 수 있습니다.\n• **기본기 강조:** 문법 문제, 특히 합성어 문제를 풀 때 형태소 분석을 습관화해야 합니다. 또한, 접속 조사와 부사격 조사처럼 대립되는 개념을 명확히 인지하고 문제에 접근해야 합니다.\n• **효율적 정보 탐색:** 자료가 많은 매체 문제에서는, 전체를 다 읽기보다 선택지 분석을 통해 필요한 정보(키워드)를 먼저 파악하고 해당 부분만 찾아 확인하는 것이 효율적입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_061', 'lesson_note', '35-36번: 문장 구조의 중의성 분석', '조창훈', '• 지문의 구조(수식 관계, 주체 범위 등)를 먼저 파악하고, 각 문단에서 설명하는 중의성의 유형을 분류하는 것이 중요합니다.\n• 부사어가 안은문장을 수식하는지(부1), 안긴문장을 수식하는지(부2)를 구분하는 방식으로 접근하면 복잡한 문장 구조를 명료하게 분석할 수 있습니다.\n• 5번 선택지의 \'하고\'는 서술어 \'친구들이다\'의 특성상 행위의 동반을 나타내는 부사격 조사가 될 수 없고, 주체를 연결하는 접속 조사로만 해석됨을 설명했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_062', 'lesson_note', '39번: 고난도 합성어 문제 분석 (\'길짐승\')', '조창훈', '• 학생들이 가장 많이 틀린 \'보스\' 문제로, 체계적인 접근이 필요했습니다.\n• **1단계:** 각 선택지에서 합성어를 2개씩 찾아내고, 합성어가 1개이거나 없는 선택지(4번, 5번)를 먼저 제외합니다.\n• **2단계:** 남은 선택지에서 \'좌우\', \'눈물\'과 같이 용언의 활용형이 포함되지 않은 명사+명사 구조의 합성어를 제외합니다.\n• **3단계:** \'길짐승\'의 어원을 정확히 분석하는 것이 핵심입니다. \'길(Street)에 사는 짐승\'이 아니라, \'기다(crawl)\'의 어간 \'기-\'에 관형사형 어미 \'-ㄹ\'이 결합하고 \'짐승\'이 붙은 **통사적 합성어**입니다. 이는 \'날짐승\'(\'날다\'의 어간 \'날-\' + \'-ㄹ\' + \'짐승\')과 대응되는 개념으로 이해해야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_063', 'lesson_note', '45번: 매체 자료 분석 전략', '조창훈', '• 다수의 학생이 어려움을 겪은 문제지만, \'레이어 쌓기\' 전략을 적용하면 효과적으로 풀 수 있습니다.\n• **접근법:** 선택지를 ①의견 반영 주체, ②변경 목적, ③변경 결과의 세 부분으로 나눕니다.\n• **검증 순서:** 가장 객관적이고 빠르게 확인할 수 있는 ③변경 결과(보기와 대화 내용 비교)부터 검증하여 오답을 소거합니다.\n• **예시:** 2번 선택지의 경우, 변경 후 목표 온도가 15도인데, 이는 자료(PDF)에 제시된 적정 온도의 \'최댓값\'이 아니므로 오답임을 빠르게 판단할 수 있습니다. 이러한 방식으로 선택지를 하나씩 제거해나가면 정답을 찾을 수 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_064', 'lesson_note', '강의 총평', '조창훈', '이번 모의고사 \'언어와 매체\' 영역은 기본적인 문법 개념의 정확한 이해와 더불어, 복잡한 정보를 체계적으로 분석하고 적용하는 문제 해결 능력을 요구했습니다. 특히 39번(합성어)과 45번(매체) 문제에서 변별력이 드러났습니다. 학생들은 어려운 문제에 매몰되기보다, 확실히 맞힐 수 있는 문제부터 해결하여 점수를 확보하는 실전적인 시험 운영 전략을 익히는 것이 중요합니다. 또한, 복잡한 문제는 여러 단계로 나누어 차근차근 해결하는 훈련을 꾸준히 해야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_065', 'lesson_note', '회의 개요', '조창훈', '이번 회의는 학생 \'지윤\'의 국어 과목 학습 부진 문제 해결을 위한 심층 1:1 코칭 세션이었습니다. 선생님은 지윤 학생의 핵심 문제가 성실성 부족이 아닌, 조급함과 불안감에서 비롯된 \'멘탈\' 문제와 어머니의 정보 과잉으로 인한 \'자기주도성 부족\'에 있다고 진단했습니다. 이에 따라, 공부 환경 정리, 자기주도적 계획 수립, 시험 운영 멘탈 관리 등 구체적인 해결책을 제시했습니다. 또한, 다음 주부터 선생님의 자체 커리큘럼을 시작할 것을 예고하며, 고난도 기출 지문(기체 법칙, 사막 형성)을 활용한 심층적인 독해 전략과 그래프 분석법을 직접 시연하며 지도했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_066', 'lesson_note', '핵심 요약', '조창훈', '선생님은 지윤 학생의 가장 큰 학습 장애물이 즉각적인 성과를 바라는 조급한 마음과 수동적인 학습 태도라고 분석했습니다. 그는 공부 방법 자체를 계속 의심하기보다, 하나의 방법을 정했으면 믿고 꾸준히 밀고 나가는 태도가 중요하다고 강조했습니다. 이를 위해 **자기주도적 학습 계획 수립**의 중요성을 역설하며, 매일 아침 스스로 그날의 공부 계획을 짜야 한다고 조언했습니다. 또한, 3월 모의고사를 앞두고 점수 자체보다 시험 시작부터 끝까지 포기하지 않고 \'운영\'하는 경험을 쌓는 것이 중요하다고 말하며, **실전 멘탈 관리법**을 상세히 지도했습니다. 특히 \'화작\'과 \'언매\' 선택 고민에 대해, 6월 모의고사 결과까지 본 후 전략적으로 결정해도 늦지 않다는 현실적인 조언을 제공했습니다. 세션 후반부에는 고난도 기출 지문을 통해 **\'구조 독해 후 정독\'**이라는 2단계 읽기 전략과 **\'축-선-점\' 순서의 그래프 분석법**을 심도 있게 설명하며 학생의 실질적인 문제 해결 능력 향상을 도모했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_067', 'lesson_note', '학생의 핵심 문제 진단: 멘탈과 주도성', '조창훈', '선생님은 지윤 학생의 근본적인 문제가 학습 능력이나 성실성이 아니라 \'멘탈\'과 \'주도성\'에 있다고 명확히 진단했습니다. 첫째로, 지윤 학생은 결과를 빨리 보고 싶어 하는 조급함 때문에 공부 과정에 온전히 집중하지 못하고 있었습니다. 이로 인해 끊임없이 \'이 방법이 맞나?\'라는 잡생각에 시달리며, 지식을 오롯이 받아들이지 못하는 상태라고 분석했습니다. 둘째로, 학생의 학습 과정에 주도성이 결여되어 있다고 지적했습니다. 어머니가 모든 정보를 탐색하고 학습 자료나 인강을 밀어 넣어 주는 방식 때문에, 지윤 학생은 수동적으로 따라가기만 할 뿐 왜 이 공부를 하는지에 대한 확신이 없었습니다. 이러한 주도성의 부재가 결국 자신이 선택하지 않은 길에 대한 불안감으로 이어져, 몸은 힘들게 공부하면서도 심리적으로는 계속 싸우고 있는 악순환을 낳고 있다고 설명했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_068', 'lesson_note', '공부 환경 및 루틴 정립의 중요성', '조창훈', '선생님은 효과적인 학습을 위한 첫 단계로 물리적인 공부 환경과 일관된 루틴을 만드는 것의 중요성을 강조했습니다. 그는 현재 지윤 학생의 책상 상태가 마음에 들지 않는다며, 공부를 시작하기 전 항상 책상을 깔끔하게 정리하는 습관을 들일 것을 지시했습니다. 구체적으로 공부할 책과 노트를 정확히 꺼내고, 필통을 가지런히 놓은 뒤 사용할 필기구만 꺼내두는 등, 공부 시작 전의 준비 과정을 하나의 \'루틴\'으로 만들라고 조언했습니다. 또한, 공부할 책이나 노트를 펼칠 때 처음부터 바로 진도를 나가는 것이 아니라, 앞부분을 훑어보며 이전에 학습했던 내용을 복기하는 \'예열\' 과정을 반드시 거쳐야 한다고 말했습니다. 이러한 매일의 작은 습관과 루틴이 흐트러진 집중력을 바로잡고, 온전히 공부에 몰입할 수 있는 상태를 만들어준다고 설명했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_069', 'lesson_note', '자기주도적 계획 수립 강조', '조창훈', '선생님은 지윤 학생이 현재의 수동적인 학습 태도에서 벗어나기 위해 반드시 스스로 학습 계획을 세워야 한다고 여러 차례 강조했습니다. 선생님 자신이 짜주는 주간 계획표는 계약상 의무일 뿐, 학생에게 실질적인 도움이 되기 어렵다고 솔직하게 이야기했습니다. 진정한 공부는 그날그날 아침, 학생 스스로가 \'오늘 국어는 무엇을, 수학은 무엇을 할 것인가\'를 결정하고 계획을 다시 짜는 것에서 시작된다고 역설했습니다. 전날 계획을 다 못 지켰다면 다음 날 계획에 반영하여 유동적으로 조정하는 능력 또한 스스로 길러야 한다고 말했습니다. 이처럼 스스로 선택하고 계획을 세우는 과정을 통해야만, 공부에 대한 주인의식을 갖고 \'이게 맞나\'라는 불필요한 의심과 싸우지 않게 될 것이라고 조언하며, 학생의 능동적인 변화를 강력하게 촉구했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_070', 'lesson_note', '인강(온라인 강의) 활용 전략', '조창훈', '지윤 학생이 강민철, 김동욱 등 유명 강사의 인강을 듣는 것에 대해 고민하자, 선생님은 인강 선택 자체보다 선택 후의 태도가 더 중요하다고 조언했습니다. 어떤 강사를 선택하든 일단 듣기로 결정했다면, 그 방법에 대해 의심하지 말고 마음을 열고 적극적으로 무언가를 얻어내려는 자세로 임해야 한다고 강조했습니다. \'이게 도움이 될까?\'라는 삐딱한 마음으로 들으면 아무것도 얻을 수 없으며, 이는 선생님의 수업을 들을 때도 마찬가지라고 지적했습니다. 또한, 인강을 듣는 것은 시간이 많이 소요되어 가성비가 떨어질 수 있다는 점을 언급하며, 특히 독서 영역에서 단순히 문제만 풀고 싶다면 어떤 교재나 강의를 선택하든 큰 차이가 없다고 설명했습니다. 중요한 것은 끊임없이 더 나은 방법을 찾아 헤매는 것이 아니라, 일단 정한 것을 믿고 꾸준히 실천하는 것이라고 재차 강조했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_071', 'lesson_note', '선생님 자체 커리큘럼 도입 계획', '조창훈', '선생님은 현재의 수업 방식이 학생의 질문을 해결해주고 과제를 관리하는 수준에 머물러 있다고 평가했습니다. 그는 자신이 구상하는 \'성적을 올리는 프로세스\'가 있지만, 현재 지윤 학생이 여러 과제에 치여 있어 새로운 것을 추가하기 어려운 상황이라고 진단했습니다. 이에, 다음 주부터는 수업 시간의 일부를 할애하여 선생님의 자체 커리큘럼을 진행하겠다고 발표했습니다. 학생의 부담을 줄이기 위해 과제는 많이 내주지 않는 대신, 수업 시간 동안 선생님의 프린트와 접근 방식을 중심으로 진도를 나갈 것이라고 설명했습니다. 이를 위해 \'기출 문제집\'을 연습용 교재로 사용할 계획이며, 이 교재를 통해 선생님이 강조하는 독해 접근법을 함께 적용하고 연습하는 시간을 가질 것이라고 밝혔습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_072', 'lesson_note', '시험 운영 및 멘탈 관리 전략', '조창훈', '지윤 학생이 모의고사에서 화작(화법과 작문)에 시간을 너무 많이 쓰고 여러 문제를 틀린 후 심리적으로 무너져 시험을 포기했던 경험을 이야기하자, 선생님은 \'시험 운영 능력\'과 \'멘탈 관리\'의 중요성을 집중적으로 코칭했습니다. 그는 시험이란 원래 생각대로 순탄하게 흘러가지 않으며, 중간에 반드시 막히는 부분이 생긴다고 말했습니다. 중요한 것은 그 순간에 당황해서 시험 전체를 놓아버리는 것이 아니라, 끝까지 1점이라도 더 얻기 위해 애쓰는 정신력이라고 강조했습니다. 특히 3월 모의고사에서는 점수에 연연하지 말고, 처음부터 끝까지 시험을 정상적으로 \'운영\'해내는 경험을 쌓는 데 집중하라고 조언했습니다. 화작에서 시간이 오래 걸리더라도 포기하지 말고, 오히려 속도를 더 내서라도 끝까지 완주하는 연습이 필요하다고 역설했습니다. 또한, \'틀리면 안 된다\'는 강박을 버리고, \'몇 개는 틀려도 괜찮다\'는 여유로운 마음으로 풀어야 오히려 더 빠르고 정확하게 풀 수 있다고 구체적인 마인드 컨트롤 방법을 제시했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_073', 'lesson_note', '\'언매\'와 \'화작\' 선택에 대한 전략적 조언', '조창훈', '화작에서의 어려움으로 \'언매\'(언어와 매체)로의 전환을 고민하는 지윤 학생에게 선생님은 매우 현실적이고 전략적인 조언을 제공했습니다. 그는 현재 다른 과목도 벅찬 상황에서 새로운 \'언매\' 개념 인강을 시작하는 것은 매우 비효율적이며 중간에 포기할 가능성이 높다고 만류했습니다. 대신, 6월 모의고사까지 화작에 집중해보고, 그때도 2개 안쪽으로 틀리는 것이 어렵다고 판단되면 여름방학 이후에 \'언매\'로 전환해도 늦지 않다고 설명했습니다. 그는 \'애매한\' 성적대의 학생들에게는 오히려 \'언매\'가 유리할 수 있다는 역설적인 분석을 내놓았습니다. 문법 5문제 중 몇 개는 틀린다고 가정하고, 빠르게 찍고 넘어감으로써 확보한 시간을 비문학이나 문학에 투자하는 것이 화작에서 시간은 시간대로 쓰고 점수도 잃는 것보다 나을 수 있다는 것입니다. 따라서 \'언매\'는 지금 당장 걱정할 문제가 아니라, 나중에 선택할 수 있는 하나의 \'전략적 카드\'로 남겨두라고 조언했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_074', 'lesson_note', 'Q&A: 기체 법칙 관련 기출 문제 심층 분석', '조창훈', '지윤 학생이 2013학년도 수능 기출 지문 중 \'이상 기체와 실제 기체\'에 대한 질문을 하자, 선생님은 심층적인 분석을 제공했습니다. 학생은 \'분자 간 인력이 작용하면 부피가 작아지고, 부피와 압력은 반비례하므로 압력이 높아져야 하는데 왜 지문에서는 압력이 낮아진다고 하는지\'에 대해 혼란스러워했습니다. 선생님은 두 가지 핵심을 지적했습니다. 첫째, 학생이 인과관계의 선후, 즉 독립변인과 종속변인을 혼동했다고 설명했습니다. 지문 상황은 \'부피가 줄어들어(독립변인)\' 분자 간 거리가 가까워지면서 \'인력이 커지는(종속변인)\' 것이지, 인력 때문에 부피가 줄어드는 순서가 아니었습니다. 둘째, \'압력이 낮아진다\'는 표현은 절대적인 감소가 아니라 \'이상 기체와 비교했을 때\' 상대적으로 낮다는 의미임을 명확히 했습니다. 즉, 부피가 줄면 실제 기체의 압력도 높아지지만, 분자 간 인력 때문에 이상 기체의 이론적 압력 값보다는 \'덜\' 높아진다는 것입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_075', 'lesson_note', '고난도 지문 독해 전략: 2단계 읽기', '조창훈', '선생님은 고난도 비문학 지문을 효과적으로 읽기 위한 \'2단계 읽기\' 전략을 제시했습니다. 첫 번째 단계는 **\'핵심어와 구조 파악\'**입니다. 지문을 처음부터 정독하는 것이 아니라, 문단별로 앞뒤를 훑어보며 핵심어(상관관계, 방정식 등)와 전체적인 글의 구조(정의-차이점-구체화-결론 등)를 예측하고 파악하는 것입니다. 이 과정에서 각 문단의 역할을 한두 단어로 \'추상화\'하여 머릿속에 지도를 그리는 것이 중요하다고 강조했습니다. 두 번째 단계는 이 구조 파악이 끝난 후에야 진행되는 **\'정독\'**입니다. 전체적인 틀을 미리 파악하고 읽으면, 다음에 어떤 내용이 나올지 예측할 수 있어 수동적으로 끌려다니지 않고 능동적으로 정보를 처리할 수 있게 됩니다. 이 방법은 시간이 없을 때 구조 파악만으로 문제를 풀어야 하는 위기 상황에도 대비할 수 있게 해준다고 설명했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_076', 'lesson_note', '그래프 분석 전략: \'축-선-점\' 기법', '조창훈', '기체 법칙 지문에 포함된 압력-부피 그래프를 분석하며, 선생님은 그래프 독해의 핵심 원칙으로 \'축, 선, 점\' 3단계를 제시했습니다.\n\n1. **축 확인**: 가장 먼저 x축(부피)과 y축(압력)이 무엇을 의미하는지 확인하고, 특히 어느 쪽이 기준이 되는 독립변인 축(기준축)인지를 파악해야 합니다. 이 그래프의 경우, 수평 보조선이 그어져 있어 y축인 \'압력\'이 기준축 역할을 하는 특이한 케이스임을 간파하는 것이 핵심이라고 강조했습니다.\n2. **선 확인**: 그래프의 각 선(점선 C: 이상기체, 실선 A/B: 실제기체)이 무엇을 나타내는지 이름을 붙여야 합니다. 이를 통해 \'압력에 따른 각 기체의 부피 변화\'라는 상관관계를 명확히 인식할 수 있습니다.\n3. **점 확인**: 교점, 극점, 변곡점 등 의미 있는 \'점\'을 찍어 변화를 분석합니다. 보조선과의 교점을 통해 동일한 압력(독립변인 통제) 하에서 각 기체(선)의 부피(종속변인)가 어떻게 다른지를 비교 분석할 수 있습니다. 이를 통해 P1까지는 인력의 영향이, 그 이후에는 반발력의 영향이 우세해짐을 추론할 수 있었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_077', 'lesson_note', '문제 풀이 전략: \'조각 토킹\'과 \'징검다리\'', '조창훈', '선생님은 사막의 형성 원인에 대한 지문을 예시로 들어, 효율적인 문제 풀이 기술을 시연했습니다. 그는 선택지를 무작정 OX로 판단하려 하지 말고, 의미 단위로 잘게 \'조각\'내어 분석하라고 조언했습니다. 그리고 각 조각에 해당하는 내용이 지문의 어느 문단에 있을지 빠르게 예측하고 찾아가는 \'조각 토킹\' 연습을 강조했습니다. 특히, 정답의 근거가 한 문장에 있지 않고 여러 문단에 흩어져 있는 \'징검다리\' 유형의 문제를 해결하는 법을 설명했습니다. 예를 들어, \'타클라마칸 사막은 온대 사막이다\'라는 선택지를 확인할 때, 3문단에서 \'타클라마칸\'을 찾고, 1문단에서 \'온대 사막\'의 정의(대륙 내부에 위치)를 찾은 뒤, 다시 3문단에서 \'타클라마칸\'이 대륙 내부에 위치함을 확인하여 세 정보를 연결하는 것입니다. 이러한 징검다리 찾기 연습을 통해 복잡한 정보 확인 문제의 정확성과 속도를 높일 수 있다고 말했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_078', 'lesson_note', '결론 및 다음 단계', '조창훈', '세션을 마무리하며 선생님은 지윤 학생에게 다시 한번 멘탈 관리와 꾸준함의 중요성을 당부했습니다. 당장의 성과에 일희일비하지 말고, 올바른 과정을 쌓아가는 데 집중할 것을 격려했습니다. 다음 수업부터는 선생님의 자체 커리큘럼을 시작하며, 오늘 배운 구조 독해 및 문제 풀이 전략을 지속적으로 연습해 나갈 것임을 재확인했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_079', 'lesson_note', 'Action Items', '조창훈', '* **지윤**: 3월 모의고사에 응시하되, 점수보다 시험 시작부터 끝까지 포기하지 않고 \'운영\'하는 경험을 쌓는 데 집중할 것.\n* **지윤**: 3월 모의고사 후 결과를 선생님에게 즉시 알릴 것.\n* **지윤**: 다음 수업 시간에 선생님의 커리큘럼 진행을 위해 \'기출 문제집\'을 지참할 것.\n* **지윤**: 매일 아침, 그날의 학습 내용을 스스로 계획하는 연습을 시작할 것.\n* **지윤**: 수업 시간 외에 발생하는 질문은 카카오톡을 통해 선생님에게 문의할 것.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_080', 'lesson_note', '강의 개요', '조창훈', '본 강의는 \'효율적 계약 파기\'와 \'비효율적 계약 파기\'를 다룬 비문학 지문에 대한 심층 분석 및 관련 문제(4번~8번) 풀이 전략을 다룹니다. 지문의 핵심 개념을 이해하고, 이를 문제에 적용하는 구체적인 방법과 선택지를 효율적으로 분석하는 패턴을 학습하는 것을 목표로 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_081', 'lesson_note', '주요 개념 정리', '조창훈', '강의에서 중점적으로 다룬 핵심 경제 및 법률 개념은 다음과 같습니다.\n\n* **효율적 계약 파기**: 계약을 이행하는 것보다 파기하고 손해배상을 하는 것이 사회 전체적으로 더 이익이 되는 경우의 계약 파기.\n* **비효율적 계약 이행**: 사회 전체적으로는 손실이 발생함에도 불구하고, 과도한 손해배상액 약정 때문에 계약 당사자가 어쩔 수 없이 계약을 이행하는 상황.\n* **기대이익**: 계약이 정상적으로 체결되고 이행되었을 경우 얻을 수 있었던 이익. 본문에서는 (효용가치 - 가격)으로 계산됩니다.\n* **경제학적 비용**: 회계 장부에 기록되는 비용(생산 비용)뿐만 아니라, 다른 선택을 함으로써 포기하게 된 이익(기회비용)까지 포함하는 비용. 즉, **경제학적 비용 = 생산 비용 + 기회비용**.\n* **과도한 신뢰 투자**: 기대이익에 근거한 손해배상액 산정 방식이 유발할 수 있는 부작용으로, 채권자가 계약 이행을 과도하게 믿고 불필요한 투자를 하는 상황.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_082', 'lesson_note', '비문학 문제 풀이 핵심 전략', '조창훈', '강사는 문제 유형에 따른 효과적인 접근법을 제시했습니다.\n\n* **위치 찾기**: 선택지의 핵심 키워드(예: 신생 기업, 경제학적 비용)를 통해 본문에서 해당 내용이 위치한 문단을 신속하게 파악합니다.\n* **선택지 분해**: 긴 선택지는 의미 단위로 잘라서 각 부분의 진위를 개별적으로 판단합니다.\n* **개념 치환**: 선택지에 나온 \'기대이익\', \'기회비용\'과 같은 개념어를 지문의 정의로 바꾸어 생각합니다. 예를 들어, \'기대이익\'을 \'계약 이행 시 얻는 이익\'으로 바꾸어 문장을 재해석합니다.\n* **부정/한정 표현 유의**: \'않았을 경우\', \'~할 수 없다\', \'~만\', \'~뿐\' 등과 같은 부정적, 단정적, 한정적 표현은 출제자의 의도가 담긴 핵심 포인트이므로 주의 깊게 분석해야 합니다.\n* **정보 재활용**: 앞선 문제(예: 5번)를 풀면서 확인한 개념 정의나 정보를 다음 문제(예: 7번) 풀이에 적극적으로 활용합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_083', 'lesson_note', '8가지 비문학 선택지 패턴', '조창훈', '강사가 강조한, 비문학 문제에서 자주 나타나는 8가지 선택지 오류 패턴입니다.\n\n1. **섞어치기**: 서로 다른 대상의 속성이나 내용을 교묘하게 섞어서 오답을 만듭니다.\n2. **부정 표현/상대어**: \'아니다\'를 \'이다\'로 바꾸거나, \'수평\'을 \'수직\'으로 바꾸는 등 반대 개념을 사용합니다.\n3. **주체/객체 변경 (후/후즈/훔)**: 문장의 주어, 소유격, 목적어 등을 바꿔서 의미를 왜곡합니다.\n4. **순서/방향 변경**: 사건의 선후 관계나 인과 관계의 방향을 뒤집습니다.\n5. **인과관계 왜곡**: 원인과 결과를 바꾸거나, 상관관계를 인과관계로 잘못 설명합니다.\n6. **상관관계 왜곡**: 양의 상관관계를 음의 상관관계로 바꾸는 등 관계의 종류를 왜곡합니다.\n7. **조건 왜곡**: 필요조건을 충분조건으로 바꾸거나, 특정 조건의 범위를 부당하게 한정하거나 확장합니다.\n8. **결합/분리**: 반드시 함께 고려해야 할 요소를 분리하거나(부당한 분리), 별개인 요소를 묶어서(부당한 결합) 오답을 구성합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_084', 'lesson_note', '문항별 상세 해설', '조창훈', '* **4번 문제 (내용 전개 방식)**: \'가\' 지문의 1문단에서 \'효율적 계약 파기\'의 개념을 제시하고 2, 3문단에서 예시를 든 구조를 파악하여 정답을 찾습니다. 각 선택지 요소가 지문의 몇 문단에 해당하는지 매칭하는 것이 중요합니다.\n* **5번 문제 (내용 일치)**: 각 선택지를 지문과 대조하며, 5번 선택지의 \'다른 계약을 통해 얻을 수 있었던 평균적인 이윤\'이 \'기회비용\'임을 파악하고, \'나\' 지문 2문단에서 경제학적 비용이 생산비용과 기회비용의 합으로 정의된 것을 확인하여 해결합니다.\n* **6번 문제 (추론)**: 3번 선택지가 오답인 이유를 인과 패턴으로 분석합니다. \'과도한 신뢰 투자\'와 \'효율적 계약 파기\'는 \'기대 이익 기반 손해배상\'이라는 **공통 원인에서 비롯된 병렬적인 결과**이지, 서로가 원인-결과 관계가 아닙니다. 선택지는 \'과도한 신뢰 투자\'가 원인이 되어 \'효율적 계약 파기\'가 일어나기 어렵다는 잘못된 인과관계를 설정했습니다.\n* **7번 문제 (사례 이해: 비효율적 계약 이행)**: \'비효율적 계약 이행\'은 계약이 \'이행\'된 상황임을 명확히 해야 합니다. 계약이 이행되었으므로 매수자(을)의 \'기대이익\'은 실현된 것입니다. 비효율성은 개인의 이익 실현 여부가 아닌, 사회 전체적인 관점에서 손실이 발생하기 때문에 붙여진 이름입니다. 2번 선택지는 \'기대이익 일부가 실현되지 못한다\'고 하여 계약이 \'이행\'되었다는 사실과 모순됩니다.\n* **8번 문제 (사례 적용)**: 주어진 사례(A=매수자, B=매도자, 가격=120, 효용=150, B의 경제학적 비용=100)를 바탕으로 각 선택지를 계산합니다. 예를 들어 1번에서 손해배상액이 40일 때, A는 효용가치가 110 밑으로 떨어지면 계약을 파기할 유인이 생깁니다. 만약 효용가치가 105가 되면 A는 파기하지만, 이는 B의 경제학적 비용 100보다 크므로 사회적으로 비효율적인 계약 파기가 발생할 수 있음을 추론할 수 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_085', 'lesson_note', '핵심 요약 및 강조 사항', '조창훈', '본 강의는 지문을 구조적으로 독해하고 문제에 접근하는 체계적인 방법을 강조했습니다. 특히, 선택지에 사용된 특정 표현(\'~만\', \'~할 수 없다\' 등)이 출제 포인트가 될 수 있음을 인지하고, 8가지 선택지 패턴을 숙지하여 문제 풀이의 정확성과 속도를 높이는 것이 중요합니다. 개념어는 단순 암기를 넘어, 문제 상황에 맞게 그 정의를 적극적으로 대입하여 해석하는 능력을 길러야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_086', 'lesson_note', '주요 개념 간의 인과 관계', '조창훈', '* **원인**: 과도한 손해배상액 약정 → **결과**: 비효율적 계약 이행 발생\n* **원인**: 기대 이익에 근거한 손해배상액 산정\n  * **결과 1**: 효율적 계약 파기 유도\n  * **결과 2**: 과도한 신뢰 투자 유발 가능성 (결과 1과 결과 2는 병렬 관계)\n* **조건**: A(매수자)의 효용가치 < B(매도자)의 경제학적 비용 → **결과**: 계약 파기가 사회적으로 효율적임');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_087', 'lesson_note', '수강생을 위한 학습 가이드', '조창훈', '* **복습**: 단순히 정답을 확인하는 데 그치지 말고, 강사가 제시한 풀이 과정, 특히 선택지를 분석하고 근거를 찾는 논리적 흐름을 그대로 따라 해보는 연습을 하십시오.\n* **개념 내재화**: \'경제학적 비용\', \'기회비용\', \'기대이익\' 등 핵심 개념은 다른 지문에서도 활용될 수 있으므로 그 정의와 의미를 정확히 암기하고 이해해야 합니다.\n* **패턴 적용**: 8가지 선택지 패턴을 숙지하고, 다른 비문학 문제를 풀 때 의식적으로 적용하여 어떤 패턴의 오류인지 분석하는 훈련을 하십시오.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_088', 'lesson_note', '강의 개요', '조창훈', '3월 모의고사를 앞두고 국어 영역 시험 운용, 지문 독해, 문제 풀이에 대한 종합적인 전략을 다루는 강의입니다. 특히 시간 관리, \'독서론\' 섹션의 효율적 풀이, 그리고 법률-경제 복합 지문과 같은 고난도 유형에 대한 심층적인 분석 및 접근법을 제시합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_089', 'lesson_note', '3월 모의고사 대비 핵심 전략', '조창훈', '**시험 운용 원칙**:\n• **즉시 마킹**: 한 지문 풀이가 끝날 때마다 답안지에 마킹하여 시간 관리 및 실수를 방지합니다.\n• **분할 독해**: 지문을 문단, 단락, 장면 단위로 나누어 읽으며 내용을 구조적으로 파악합니다.\n• **예측하며 읽기**: 앞으로 나올 내용을 예측하고, 이전 내용과 연결하며 통합적으로 이해합니다.\n\n**비문학 지문 접근법**:\n• **구조 선행 파악**: 지문을 바로 읽기 시작하지 말고, 전체 문단 구성을 먼저 확인하여 내용의 전체적인 흐름과 구조(맵)를 파악한 후 정독합니다.\n• **시간 부족 시 대응**: 시간이 급할 경우, 정독 대신 구조 파악만으로도 문제를 풀 수 있는 가능성을 열어두어야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_090', 'lesson_note', '문제 유형별 접근법', '조창훈', '• **선택지 분석**: 선택지 5개를 먼저 명제 단위로 분석하고, 어떤 것부터 판별할지 전략적으로 결정합니다. 하나의 선택지에 매몰되지 않도록 합니다.\n• **근거 표시**: 지문에서 답의 근거를 찾았을 경우, 눈으로만 확인하지 말고 반드시 흔적을 남겨 재확인을 방지합니다.\n• **\'조건 게임\' 유형**: 발문에서 특정 위치가 지정된 문제의 경우, 해당 부분을 찾아 핵심 조건을 문제지 여백에 메모한 후, 그 메모를 기반으로 선택지를 판단합니다.\n• **\'섞어치기\' 유형**: 두 가지 대립되는 개념(예: 종이책 vs 디지털 환경)을 교묘하게 섞어 놓은 선택지를 항상 경계해야 합니다. 각 요소가 어떤 개념에 속하는지 명확히 구분합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_091', 'lesson_note', '3월 모의고사를 대하는 마음가짐', '조창훈', '• **목표 설정**: 점수 자체에 연연하기보다, 80분간의 시험 운용 능력(시간 배분, 집중도 유지)을 점검하고 자신만의 시험 루틴을 확립하는 것을 목표로 삼아야 합니다.\n• **과정 점검**: 본문 표시, 선택지 분석 등 평소 연습한 풀이 과정을 실전에서 어느 수준까지 적용할지 결정하고 연습하는 시험으로 활용합니다.\n• **자만 경계**: 3월 모의고사 성적이 수능까지 이어진다는 보장은 없습니다. 특히 3월에 좋은 성적을 받은 학생들이 이후에 성적이 하락하는 경우가 많으므로, 결과에 일희일비하지 않고 꾸준히 학습을 이어가야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_092', 'lesson_note', '\'독서론\' (1-3번) 풀이 전략: 구조 독해', '조창훈', '\'독서론\' 파트는 정독 대신 \'구조 독해\'를 활용하여 시간을 단축하는 것이 핵심입니다.\n\n1. **전체 핵심어 파악**: 지문 전체를 관통하는 핵심어를 빠르게 찾습니다. (예: 심층 독해)\n2. **문단별 기능 추상화**: 각 문단의 역할을 한두 단어로 추상화하여 정리합니다.\n   - **1문단**: \'심층 독해\'와 \'독서 회로\'의 개념 정의 및 논의 배경\n   - **2문단**: 디지털 환경(하이퍼텍스트)에서의 읽기가 가진 문제점\n   - **3문단**: 종이책 읽기의 효용성 (심층 독해 능력 발달)\n   - **4문단**: 전체 내용의 의의 및 정리\n3. **구조 기반 풀이**: 세부 내용을 모두 읽지 않고, 파악된 구조만으로 풀 수 있는 문제부터 빠르게 해결합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_093', 'lesson_note', '심층 분석: 법률-경제 복합 지문 (4-9번)', '조창훈', '고난도 복합 지문은 디테일에 매몰되기 전, 거시적인 구조를 파악하는 것이 매우 중요합니다.\n\n### 지문 독해 프로세스\n\n1. **맵핑 (구조 독해)**: 문단별로 핵심 내용과 역할을 개괄적으로 파악하여 지문 전체의 논리적 흐름을 그립니다. (예: (가)지문 - 효율적 계약 파기 개념/사례 → (나)지문 - 비효율적 계약 파기 방지를 위한 \'기대 이익\' 개념 도입)\n2. **개념 체킹**: 각 지문에서 새로 등장하는 핵심 개념(효율적 계약 파기, 효용 가치, 손해 배상액, 기대 이익, 경제학적 비용 등)을 명확히 표시하고 그 관계를 파악합니다.\n3. **정독 및 구체화**: 구조 파악 후, 지문에 제시된 구체적인 수치와 사례를 통해 개념을 이해합니다. (예: 계약금 100, 하락한 효용 가치 50, 손해배상액 20 등을 대입하여 상황 시뮬레이션)\n4. **수식 정리**: 계약 파기 조건과 같은 핵심 논리를 수식으로 정리하여 문제 풀이에 활용합니다. (예: **계약 파기 조건: 손해배상액 < (계약 가격 - 실제 효용 가치)**)\n\n### 핵심 개념 이해\n\n• **효율적 계약 파기**: 한쪽이 계약을 파기하고 손해배상을 하더라도, 그 자원이 더 높은 가치를 창출할 수 있는 제3자에게 가는 것이 사회 전체적으로 더 이익이 되는 상황.\n• **기대 이익 기반 손해 배상**: 계약이 정상적으로 이행되었을 때 얻었을 이익을 기준으로 손해배상액을 산정하여, 비효율적인 계약 파기를 방지하는 방법.\n• **자원의 효율적 배분**: 개인의 손익을 넘어, 사회 전체의 총 이익(잉여)이 극대화되는 상태를 의미. 경제학의 공리주의적 관점이 바탕이 됨.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_094', 'lesson_note', '강사의 핵심 강조 사항', '조창훈', '• **\'모델\' 구축 능력**: 선택지를 판단할 때, 해당 내용이 참 또는 거짓이 되게 하는 본문의 상황(모델)을 머릿속으로 예측하고 찾아내는 훈련이 국어 문제 해결 능력의 핵심입니다.\n• **적극적이고 흔적을 남기는 읽기**: 눈으로만 읽는 소극적 독해를 지양하고, 지문에 근거를 표시하고 선택지를 분해하는 등 적극적인 사고 과정의 흔적을 남겨야 실력이 향상됩니다.\n• **패턴화된 풀이 지양**: 모든 지문과 문제를 동일한 방식으로 풀지 말고, 지문 유형과 문제의 요구에 따라 구조 독해와 정독의 비중을 조절하는 유연한 전략을 사용해야 합니다.\n\n\n# 국어 모의고사 지문 심층 분석 및 문제 풀이 전략 강의');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_095', 'lesson_note', '회의 개요', '조창훈', '본 강의는 국어 모의고사 비문학 지문(16번-21번)과 문학 작품(43번-45번)에 대한 심층 분석 및 문제 풀이 전략을 다루었습니다. 강사는 지문을 구조적으로 독해하는 방법, 문제 유형별 접근법, 그리고 문학 작품을 감상하고 해석하는 구체적인 가이드를 제공하여 학생들의 실전 문제 해결 능력을 향상시키는 데 중점을 두었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_096', 'lesson_note', '지문 분석 전략: 구조적 독해', '조창훈', '강사는 긴 글을 효과적으로 읽기 위한 첫 단계로 \'구조적 독해\'를 강조했습니다. 세부 내용을 읽기 전에 글의 전체적인 틀을 파악하는 것이 중요하며, 이는 다음과 같은 장점이 있습니다.\n\n*   **내용 예측:** 글의 전개 방향을 미리 예측하여 독해의 효율성을 높입니다.\n*   **시간 관리:** 시험 상황에서 시간이 부족할 때 핵심 내용만 빠르게 파악하는 데 유용합니다.\n*   **정독 보조:** 구조를 먼저 이해한 뒤 정독하면 내용이 더 명확하게 정리됩니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_097', 'lesson_note', '(가) 지문 심층 분석: 조선 시대 공론 정치', '조창훈', '*   **1문단:** 조선 시대의 핵심 운영 원칙인 \'공론(公論)\'의 개념을 소개했습니다. 공론은 국가 운영의 중요한 이념으로 자리 잡았습니다.\n*   **2문단:** 공론 정치의 전개 과정에서 \'붕당(朋黨)\'이 형성되었음을 설명했습니다. 초기에는 긍정적 역할을 했으나, 숙종 이후 시대가 흐르면서 점차 폐해가 발생하는 \'통시적\' 변화를 보였습니다.\n*   **3문단:** 붕당 정치의 폐해를 해결하기 위한 \'정조\'의 노력을 다루었습니다. 정조는 \'격쟁 제도\'와 \'규장각\' 운영을 통해 공론의 중심을 임금에게 두고 백성의 의견을 직접 수렴하고자 했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_098', 'lesson_note', '(나) 지문 심층 분석: 향회, 민회, 그리고 정약용', '조창훈', '*   **1문단:** 지방 자치 기구인 \'향회(鄕會)\'를 소개하고, 시간이 흐르면서 부농층이 주도권을 장악하자 수령(지방관)의 불신을 사 역할이 축소되는 과정을 설명했습니다.\n*   **2문단:** \'삼정의 문란\'으로 인한 백성들의 고통과, 이에 대응하여 조직된 자발적 저항 기구인 \'민회(民會)\'의 등장을 다루었습니다. 민회는 수탈에 저항하고 집단행동을 조직했습니다.\n*   **3문단:** 실학자 \'정약용\'이 백성을 정치적 권리를 가진 주체로 인식했음을 강조했습니다. 그의 사상은 민회와 같은 백성들의 자발적 움직임과 맞물려 사상적 기반이 되었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_099', 'lesson_note', '문제 풀이 해설 (16번 ~ 20번)', '조창훈', '*   **17번:** 중앙 정부의 \'중앙 집권화 정책\'이 향회 역할을 \'축소\'시켰으므로, \'적극적 지원\'은 사실과 다릅니다.\n*   **18번:** \'조건 게임\' 유형 문제로, 정조가 \'격쟁\'을 통해 **특정 붕당의 영향력을 약화**시키고 **임금이 주도**하여 민의를 수렴하려 한 목적을 정확히 파악해야 합니다.\n*   **19번:** \'결합 분리 패턴\'의 오답 유형입니다. 민회는 정약용 사상의 \'영향을 받아\' 형성된 것이 아니라, \'자발적\'으로 발생하여 정약용 사상과 \'맞물리며\' 발전했습니다. 인과관계를 왜곡한 선택지입니다.\n*   **20번:** 보기(4.19 혁명)와 지문을 연관 짓는 \'복수 참조\' 문제입니다. 이승만 하야는 국민이 독재에 저항하여 일방적으로 물러나게 한 것이므로, 붕당 간의 상호 작용인 \'견제와 균형\' 원리가 작동한 결과로 볼 수 없습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_100', 'lesson_note', '문학 작품 분석', '조창훈', '*   **김남조, \'겨울 바다\':**\n    *   **핵심 개념:** 시인의 기독교적 배경과 \'관조적\' 태도를 이해하는 것이 중요합니다. \'관조\'는 대상과 거리를 두고 바라보며 깨달음을 얻는 태도입니다.\n    *   **주제:** 실연의 아픔과 허무(\'허무의 불\')를 시간의 흐름과 종교적 믿음(\'기도\')을 통해 극복하고, 내면적 성숙(\'인고의 물\')에 이르는 과정을 그립니다. 이를 \'슬픔의 종교적 승화\'로 설명했습니다.\n    *   **표현:** 사랑이라는 \'추상적 대상을 구체화\'하는 표현이 특징적입니다.\n\n*   **박남준, \'흰 부추꽃으로\':**\n    *   **주제:** 삶의 상처와 고통(\'옹이 박힌 나무\')이 오히려 더 뜨거운 열정으로 타오르는 원동력이 되며, 소멸(\'흰 재\')이 새로운 생성(\'흰 부추꽃\')으로 이어지는 \'환생\'의 세계관을 보여줍니다.\n    *   **결론:** 두 작품 모두 고통이나 시련이 반드시 부정적인 것만은 아니며, 성장과 성숙, 새로운 생성의 계기가 될 수 있다는 공통된 주제 의식을 가집니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_101', 'lesson_note', '핵심 학습 전략 및 개념 정리', '조창훈', '*   **관조(觀照):** 대상에 개입하지 않고 거리를 둔 채 바라보며, 그 과정에서 깨달음을 얻는 문학적 태도입니다.\n*   **종교적 승화:** 개인적인 슬픔이나 고통을 종교적 믿음을 통해 더 높은 차원의 가치로 극복하는 것을 의미합니다.\n*   **복수 참조 문제:** 보기와 여러 지문이 함께 나올 경우, 하나의 기준(예: 보기)을 중심으로 먼저 판단하여 문제의 복잡성을 줄이는 전략이 유효합니다.\n*   **결합 분리 패턴:** 지문에서는 별개로 존재하는 두 요소를 선택지에서 인과관계로 묶어 오답을 만드는 유형에 주의해야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_102', 'lesson_note', '과제', '조창훈', '*   배부된 과제물을 제한 시간 내에 풀고 온라인으로 제출합니다.\n*   귀가 시 새로운 과제물을 수령합니다.\n\n# 현대시 심층 분석 강의: 조지훈 「마음의 태양」과 정만영 「향수」');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_103', 'lesson_note', '수업 개요', '조창훈', '조지훈 시인의 「마음의 태양」과 정만영 시인의 「향수」 두 작품을 중심으로 현대시를 심층 분석하고, 관련 문학 개념 및 문제 풀이 전략을 다룬 수업입니다. 시의 구조적 특징, 상징적 의미, 주요 표현법을 상세히 해설하며, 작품 간 연계 가능성과 시험 출제 포인트를 강조했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_104', 'lesson_note', '주요 작품 분석: 조지훈, 「마음의 태양」', '조창훈', '조지훈 시인의 대표작으로, 고난과 시련을 극복하고 이상적인 정신 세계에 도달하려는 의지를 노래한 시입니다.\n\n- **시인 배경**: **조지훈**은 **박목월**, **박두진**과 함께 **청록파** 시인으로, 자연과 전통에 대한 관심을 시에 담았습니다.\n- **핵심 주제**: 현실의 고난을 긍정적으로 수용하여 내면의 이상향(마음의 태양)을 추구하는 의지적 자세.\n- **긍정적 시어 (Good)**: 화자가 지향하는 이상적 가치를 상징합니다.\n  • **하늘, 맑은 넋, 마음의 태양(원광)**: 높고 아름다운 이상 세계.\n  • **해바라기, 노고지리**: 이상을 추구하는 존재로 화자와 동일시됩니다.\n- **부정적 시어 (Bad)**: 화자가 극복해야 할 현실의 시련을 의미합니다.\n  • **가시밭길, 눈물의 이슬, 육신의 괴로움**: 고통스러운 현실 상황.\n- **주요 표현 및 개념**:\n  • **생명력**: 시련 속에서도 삶의 아름다움을 피워내는 힘. \'눈물의 이슬\'을 양분으로 피는 \'꽃\'에서 드러납니다.\n  • **의지적 어조**: "~하게 하라"와 같은 명령형 어미를 통해 스스로에 대한 다짐과 의지를 표현합니다.\n  • **역설법**: "슬픔도 오히려 아름답다"와 같이 모순된 표현을 통해 고난을 극복한 경지를 드러냅니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_105', 'lesson_note', '주요 작품 분석: 정만영, 「향수」', '조창훈', '정만영 시인의 작품으로, 고달픈 현실 속에서 고향을 그리워하며 위안을 얻고 싶어 하는 마음을 감각적 이미지로 형상화했습니다.\n\n- **시인 배경**: **정만영**은 이미지 묘사에 뛰어난 시인으로, 회화적(pictorial)인 시풍이 특징입니다. (다른 작품: 「달포도 잎사귀」)\n- **핵심 주제**: 현실의 고단함과 고향에 대한 그리움.\n- **중심 상징 \'바다\'**: 화자의 내면을 이끌어내는 다층적 공간으로 기능이 변화합니다.\n  1. **배경**: 과거를 회상하게 하는 풍경.\n  2. **교감의 대상**: 화자에게 말을 거는 존재.\n  3. **위안의 공간**: \'어머니\'의 품처럼 안식을 얻고 싶은 공간.\n- **주요 표현 및 개념**:\n  • **공감각적 심상**: "바다 소리에 젖는다"는 표현에서 **청각의 촉각화**가 나타납니다.\n  • **추상적 대상의 구체화**: \'생활\'을 \'차다\'(촉각), \'향수\'를 \'은색\'(시각), \'추억\'을 \'찢어진 천막\'으로 표현하여 관념을 감각적으로 형상화했습니다.\n  • **도치법**: "나는 찢어진 추억의 천막을 깁는다. 모래벌에 주저앉아" 부분에서 문장 순서를 바꿔 의미를 강조합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_106', 'lesson_note', '핵심 문학 개념 정리', '조창훈', '수업에서 강조된 주요 문학 개념은 다음과 같습니다.\n\n- **역설법**: 겉으로는 모순되지만 깊은 진실을 담고 있는 표현. \'A와 B 두 부분으로 나눌 수 있는가\'와 \'두 부분이 논리적으로 양립 불가능한가\'를 통해 판단할 수 있습니다.\n- **의지적 표현**: 1인칭 화자가 부정적 상황 속에서 무언가를 다짐할 때 사용되며, 서술어에 \'-겠-\'을 넣어 의미가 통하는지 확인하여 판단할 수 있습니다.\n- **변증법적 구조**: 헤겔의 \'정(正)-반(反)-합(合)\' 논리를 문학에 적용한 것. 「마음의 태양」에서는 **현실의 고난(정)** → **긍정적 수용(반)** → **이상향 도달(합)**의 구조로 해석될 수 있습니다.\n- **감각적 형상화**: \'왓(What)-하우(How)\' 분석틀을 통해 표현 대상을 어떻게 감각적으로 표현했는지 분석하는 방법입니다. 공감각, 추상적 대상의 구체화 등을 이해하는 데 유용합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_107', 'lesson_note', '연계 작품 및 출제 포인트', '조창훈', '- 조지훈의 「마음의 태양」은 청록파 시인인 **박두진의 「해」, 「청산도」**와 엮여 \'밝음\'과 \'이상향\'의 이미지를 비교하는 문제로 출제될 수 있습니다.\n- 역설법 개념은 **다른 작품(예: 깊은 흙)과 묶여** 공통된 표현 방식을 묻는 문제로 나올 가능성이 높습니다.\n- 정만영의 「향수」는 그의 다른 작품 **「달포도 잎사귀」**와 함께 **회화적 이미지**와 **감각적 표현**을 중심으로 문제가 구성될 수 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_108', 'lesson_note', '문제 풀이 전략 및 해설', '조창훈', '- **보기 문제 분석 (10번)**: 보기에서 제시된 \'바다\'의 다층적 의미(배경→교감→위안)를 기준으로 선택지를 분석. 선택지 4번의 "고단함을 성공적으로 이겨냈다"는 시에서 \'이겨내고 싶다\'는 소망으로 나타나므로 시제가 틀렸음을 지적했습니다.\n- **\'조건 게임\' 문제 풀이법 (11번)**: "기억과 니은에 대한 이해"처럼 특정 위치가 지정된 문제는, 해당 부분을 먼저 서술형으로 정리한 후 선택지를 확인하는 것이 정확하고 빠릅니다.\n  • **기억**: \'고향\'에 대한 직접적인 \'그리움\'의 정서 표출.\n  • **니은**: \'찢어진 추억\'을 \'깁는\' 행위를 통해 상처를 치유하려는 태도. (추상적 대상의 구체화)\n- **시험 전략**: 선택지의 단어 하나하나(예: "성공적으로", "이겨냈다")에 주의하고, 시의 내용과 시점을 정확히 대응시켜야 함정을 피할 수 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_109', 'lesson_note', '시 독해 방법론', '조창훈', '- **초기 접근**: 시를 읽을 때 복잡하게 생각하기보다 그림을 그리듯 상상하고, 긍정적(Good) 요소와 부정적(Bad) 요소를 나누어 전체적인 분위기를 파악합니다.\n- **4요소 분석**: 시의 내용을 **행위, 묘사, 정서, 내면(생각)**의 네 가지로 구분하며 읽으면 구조적 이해에 도움이 됩니다.\n- **표현법 분석**: \'왓(What, 표현 대상)\'과 \'하우(How, 표현 방식)\'를 구분하여 생각하면 공감각, 구체화 등 어려운 표현법을 쉽게 파악할 수 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_110', 'lesson_note', '과제 및 다음 활동', '조창훈', '- **박두진** 시인의 **「해」**와 **「청산도」** 작품 자료를 통해 「마음의 태양」과의 연관성을 학습해야 합니다.\n- 해당 자료는 과제로 배부될 예정이므로, 미리 풀어보고 분석해 올 것이 요구됩니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_111', 'lesson_note', '강의 개요', '조창훈', '본 강의는 한국어 문법의 핵심 요소인 피동과 사동 표현에 대한 심층적인 분석을 제공합니다. 파생적 및 통사적 피동/사동의 개념을 설명하고, \'이중 피동\'과 같은 흔한 오류를 분석합니다. 또한, \'밝혀지다\', \'알려지다\'와 같은 함정 사례와 \'지나친 사동 표현\'의 올바른 사용법을 다룹니다. 강의의 최종 목표는 수강생들이 다양한 문맥에서 피동과 사동을 정확히 구별하고 올바르게 사용할 수 있도록 돕는 것입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_112', 'lesson_note', '핵심 개념 정리', '조창훈', '* **피동(Passive)**: 주어가 다른 주체에 의해 동작을 당하는 것을 나타내는 표현입니다. (예: 잡히다)\n* **사동(Causative)**: 주어가 남에게 동작을 하도록 시키는 것을 나타내는 표현입니다. (예: 먹이다)\n* **파생적 표현(Derivational)**: 동사 어간에 특정 접미사(피동 접미사: 이, 히, 리, 기 / 사동 접미사: 이, 히, 리, 기, 우, 구, 추)를 붙여 만드는 방식입니다.\n* **통사적 표현(Syntactic)**: 문장 구조 자체를 변경하여 만드는 방식으로, 보조 용언 등을 활용합니다. (피동: `-어지다`, `-게 되다` / 사동: `-게 하다`)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_113', 'lesson_note', '피동 표현 심층 분석', '조창훈', '* **파생적 피동**: 동사 어간에 피동 접미사 **이, 히, 리, 기**를 붙여 만듭니다. (예: 보이다, 잡히다)\n* **통사적 피동**: 용언에 **`-어지다`**나 **`-게 되다`**를 붙여 만듭니다. (예: 만들어지다, 알게 되다)\n* **이중 피동**: 파생적 피동과 통사적 피동을 중복으로 사용하는 문법적 오류입니다. 이는 반드시 피해야 합니다.\n  * **잘못된 예시**: `불리워지다` (부르다 + -리- + -우-(사동) + -어지다), `잊혀지다` (잊다 + -히- + -어지다)\n  * **올바른 표현**: `불리다`, `불려지다` / `잊히다`, `잊어지다`');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_114', 'lesson_note', '사동 표현 심층 분석', '조창훈', '* **파생적 사동**: 동사 어간에 사동 접미사 **이, 히, 리, 기, 우, 구, 추** 또는 접사 **`-시키다`**를 붙여 만듭니다.\n  * **이히리기우구추**: `먹이다`, `넓히다`, `알리다`, `웃기다`, `재우다`\n  * **-시키다**: `공부시키다`, `운동시키다` (명사 뒤에 붙어 파생어를 만듦)\n* **통사적 사동**: 용언에 연결어미 **`-게`**와 보조 용언 **`하다`**를 결합하여 만듭니다. (예: 먹게 하다, 가게 하다)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_115', 'lesson_note', '직접 사동과 간접 사동', '조창훈', '* **개념**: 사동문에서 주어가 행위에 직접 관여하는지(직접 사동), 말이나 지시로 유도하는지(간접 사동)에 따른 구분입니다.\n* **파생적 사동 (단형 사동)**: **직접, 간접**의 의미를 모두 가질 수 있습니다. (예: 엄마가 아이에게 옷을 **입혔다** - 직접 입혀주거나, 입으라고 말로 시키는 것 둘 다 가능)\n* **통사적 사동 (장형 사동)**: 주로 **간접**의 의미로 사용됩니다. (예: 엄마가 아이에게 옷을 **입게 했다** - 말로 시키는 경우에만 해당)\n* **예외**: 이 구분은 절대적인 규칙이 아니며, 동사의 의미에 따라 달라질 수 있습니다. 예를 들어, `채우다` (물을 컵에 채우다)는 주어가 반드시 행위에 개입해야 하므로 **직접 사동**만 가능하며, 간접의 의미로는 사용될 수 없습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_116', 'lesson_note', '주요 함정 및 예외 사항', '조창훈', '* **`밝혀지다`, `알려지다`**: 형태상 이중 피동처럼 보이지만, `밝히다`와 `알리다`가 사동사이기 때문에 **\'사동사 + -어지다\'** 구조의 정상적인 피동 표현입니다.\n* **지나친 사동 표현 금지**: `교육하다`, `소개하다`, `환기하다`와 같이 단어 자체에 사동의 의미가 포함된 경우, 불필요하게 `-시키다`를 붙이지 않는 것이 원칙입니다.\n  * **잘못된 예시**: `교육시키다`, `소개시켜 줘` (단, 주어가 행위를 직접 하지 않고 제3자에게 시키는 문맥에서는 사용 가능. 예: 선생님이 반장에게 교실을 **환기시켰다**)\n* **이중 사동 허용**: 이중 피동과 달리, 이중 사동은 일부 허용됩니다. 사동 접미사 **`-이우-`**가 결합된 형태가 대표적입니다.\n  * **예시**: `재우다(자-이-우-다)`, `세우다(서-이-우-다)`, `채우다(차-이-우-다)`\n* **피동사인 타동사**: 대부분의 피동사는 목적어를 갖지 않는 자동사이지만, 일부 피동사는 목적어를 가질 수 있습니다. 이 때문에 \'목적어 유무\'로 피동/사동을 구별하는 방법은 위험합니다.\n  * **예시**: `나는 강도에게 돈을 **빼앗겼다**.` (`빼앗기다`는 피동사지만 \'돈을\'이라는 목적어를 가짐)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_117', 'lesson_note', '피동과 사동의 구별법', '조창훈', '피동과 사동 접미사로 모두 쓰이는 **\'이, 히, 리, 기\'**를 구별하는 것이 핵심입니다. 가장 효과적인 방법은 통사적 표현으로 바꾸어 의미를 확인하는 것입니다.\n\n1. **기본형 파악**: 구별하려는 동사의 기본형(주동사/능동사)을 확인합니다.\n2. **통사적 표현 대입**: 문장의 주어를 그대로 둔 채, 동사를 아래 두 가지 형태로 바꾸어 봅니다.\n   * **피동 확인**: **`-어지다`**를 붙여본다.\n   * **사동 확인**: **`-게 하다`**를 붙여본다.\n3. **의미 판단**: 두 표현 중 어느 쪽이 원래 문장의 의미와 더 가까운지 판단합니다.\n   * **예시 `산이 보이다`**: \'산이 보아지다\' (O, 의미 자연스러움) vs \'산이 보게 하다\' (X, 의미 어색함) → **피동**\n   * **예시 `동생에게 책을 읽히다`**: \'동생에게 책이 읽어지다\' (X, 의미 어색함) vs \'동생에게 책을 읽게 하다\' (O, 의미 자연스러움) → **사동**');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_118', 'lesson_note', '핵심 요약 및 결론', '조창훈', '피동과 사동은 주어와 서술어의 관계를 통해 구분되며, 파생적 방법과 통사적 방법으로 실현됩니다. 이중 피동은 문법적 오류이므로 피해야 하지만, 일부 이중 사동은 허용됩니다. \'이, 히, 리, 기\'가 쓰인 경우, 목적어 유무와 같은 단순한 규칙에 의존하기보다 **`-어지다`**와 **`-게 하다`**를 대입하여 문맥적 의미를 판단하는 것이 가장 정확하고 안전한 구별법입니다. 문법 규칙의 예외 사항을 인지하고, 각 단어의 본래 의미를 중심으로 분석하는 능력이 중요합니다.\n\n# 한국어 문법 심화 강의: 시제와 상을 중심으로 한 시간 표현 완전 정복');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_119', 'lesson_note', '강의 개요', '조창훈', '본 강의는 한국어의 시간 표현, 특히 **시제(Tense)**와 **상(Aspect)**에 대한 심도 있는 분석을 제공합니다. 주요 문법 요소인 선어말 어미와 관형사형 전성 어미의 역할을 동사와 형용사에 따라 구분하여 설명하고, 수험생들이 혼동하기 쉬운 **절대 시제와 상대 시제**의 개념을 명확히 정리합니다. 또한, 영어의 진행형 및 완료형과 비교하며 한국어의 **진행상과 완료상**을 분석하고, \'꽃이 피었다\'나 착용 동사와 같이 중의적으로 해석될 수 있는 표현들을 다룹니다. 마지막으로 \'았/었\'과 \'겠\'이 가진 다양한 의미를 심화 학습하여 시간 표현에 대한 완전한 이해를 목표로 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_120', 'lesson_note', '주요 개념 정리', '조창훈', '*   **발화시**: 화자가 말을 하는 시점입니다.\n*   **사건시**: 문장 속 동작이나 상태가 일어나는 시점입니다.\n*   **시제 관계**:\n    *   **과거**: 사건시 < 발화시\n    *   **현재**: 사건시 = 발화시\n    *   **미래**: 사건시 > 발화시');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_121', 'lesson_note', '시제 표현 분석', '조창훈', '시제는 주로 선어말 어미와 관형사형 전성 어미를 통해 실현되며, 동사와 형용사에 따라 다른 형태를 사용하므로 주의가 필요합니다.\n\n*   **과거 시제**\n    *   **선어말 어미**: `-았-/-었-`, `-더-` (회상)\n    *   **관형사형 어미**: \n        *   동사: `-(으)ㄴ` (예: 먹은, 간)\n        *   형용사: `-던` (예: 예쁘던)\n\n*   **현재 시제**\n    *   **선어말 어미**:\n        *   동사: `-ㄴ-/-는-` (예: 간다, 먹는다)\n        *   형용사: 없음 (기본형 사용, 예: 예쁘다)\n    *   **관형사형 어미**:\n        *   동사: `-는` (예: 가는, 먹는)\n        *   형용사: `-(으)ㄴ` (예: 예쁜)\n\n*   **미래 시제**\n    *   **선어말 어미**: `-겠-`\n    *   **관형사형 어미**: `-(으)ㄹ` (예: 갈, 먹을)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_122', 'lesson_note', '절대 시제와 상대 시제', '조창훈', '복잡한 문장에서 시제를 판단하는 두 가지 기준입니다.\n\n*   **절대 시제**: **발화시**를 기준으로 각 서술어의 시제를 판단합니다. 문장의 모든 서술어는 각각의 절대 시제를 가집니다.\n    *   예시: `어제 도서관에서 공부하던 영수를 만났다`\n        *   `만났다`(서1): 과거 (발화 시점 이전에 만남)\n        *   `공부하던`(서2): 과거 (발화 시점 이전에 공부함)\n\n*   **상대 시제**: **주절 서술어(서1)의 사건시**를 기준으로 종속절 서술어(서2)의 시제를 판단합니다. 주절(서1)은 기준점이므로 상대 시제가 없습니다.\n    *   예시: `어제 도서관에서 공부하던 영수를 만났다`\n        *   `만났다`(서1): 기준점이므로 상대 시제 없음\n        *   `공부하던`(서2): 현재 (만났던 그 시점에 공부하는 동작이 진행 중이었음)\n    *   예시: `오늘 공부하는 내용이 내일 기억날 거야`\n        *   `기억날 거야`(서1): 기준점이므로 상대 시제 없음\n        *   `공부하는`(서2): 과거 (기억이 날 미래 시점을 기준으로 보면, 공부하는 것은 그 이전의 일임)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_123', 'lesson_note', '상(Aspect) 표현 분석', '조창훈', '동작의 진행 또는 완료 양상을 나타내는 문법 범주로, 진행상과 완료상으로 나뉩니다.\n\n*   **진행상 (Progressive Aspect)**: 동작이 진행 중임을 나타냅니다.\n    *   `-고 있다` (예: 밥을 먹고 있다)\n    *   `-는 중이다` (예: 공부하는 중이다)\n    *   **`-어/아 가다`** (예: 다 먹어 간다) -> 완료상과 혼동하기 쉬우므로 암기 필요\n\n*   **완료상 (Perfective Aspect)**: 동작이 완료되었거나 그 결과 상태가 지속됨을 나타냅니다.\n    *   **`-어/아 있다`** (예: 의자에 앉아 있다)\n    *   `-어/아 버리다` (예: 다 먹어 버렸다 - 현재 남은 것이 없다는 결과 포함)\n    *   **상태의 지속**: 동작은 과거에 완료되었으나, 그 결과 상태가 현재까지 지속되는 경우. (예: 꽃이 피어 있다)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_124', 'lesson_note', '중의적 시간 표현 사례', '조창훈', '하나의 문장이 문맥에 따라 다른 시간 표현으로 해석될 수 있는 경우입니다.\n\n1.  **`꽃이 피었다`**\n    *   **단순 과거 시제**: 피는 동작이 과거에 일어났으며, 현재 상태는 알 수 없음.\n    *   **완료상**: 과거에 피어서 현재까지 그 상태가 지속됨. (`꽃이 피어 있다`와 동일한 의미)\n\n2.  **착용 동사 + `-고 있다`** (예: 옷을 입고 있다, 시계를 차고 있다)\n    *   **진행상**: 현재 그 착용 동작을 하고 있는 중임.\n    *   **완료상**: 착용 동작은 이미 끝났고, 그 착용 상태가 현재까지 지속됨.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_125', 'lesson_note', '주요 문법 요소 심화 분석: \'았/었\'과 \'겠\'', '조창훈', '\'았/었\'과 \'겠\'은 기본적인 시제 표현 외에 다양한 의미를 가집니다.\n\n*   **\'-았-/-었-\'의 다른 용법**\n    *   **미래에 대한 확신**: 미래에 확실히 일어날 일에 사용. (예: 너 이제 집에 가면 **죽었다**.)\n    *   **완료 및 상태 지속**: 동작 완료 후 상태가 지속됨을 나타냄. (예: 꽃이 **피었다**.)\n\n*   **\'-겠-\'의 다양한 의미** (본래 \'추측\'의 선어말 어미)\n    *   **추측**: 미래, 현재, 과거 사실에 대한 추측. (예: 밖에 비가 **오겠다**, 옛날에는 예뻤**겠**네.)\n    *   **의지**: 1인칭 주어와 함께 쓰여 강한 의지를 나타냄. (예: 나는 서울대에 꼭 **가겠다**.)\n    *   **가능성/능력**: 어떤 일이 일어날 수 있는 가능성이나 주체의 능력을 나타냄. (예: 그런 것은 삼척동자도 **알겠다**.)\n    *   **완곡한 표현**: 상대방의 의사를 묻거나 자신의 의견을 부드럽게 표현. (예: 잠시 들어가도 **좋겠습니까**?)');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_126', 'lesson_note', '핵심 요약 및 강조점', '조창훈', '*   동사와 형용사에 따라 관형사형 어미 `-(으)ㄴ`의 시제가 달라짐을 명확히 구분해야 합니다. (**동사+은: 과거**, **형용사+은: 현재**)\n*   상대 시제는 주절(서1)의 사건시가 기준이며, 종속절(서2)에만 적용된다는 원칙을 기억해야 합니다.\n*   진행상 `-어/아 가다`와 완료상 `-어/아 있다`는 형태가 비슷하여 혼동하기 쉬우므로 반드시 구별하여 암기해야 합니다.\n*   \'상태의 지속\' (예: 꽃이 핀 상태, 옷을 입은 상태)은 동작 완료 후 결과가 이어지는 **완료상**의 개념으로 이해해야 합니다.\n\n# 수능 비문학 독해 전략 강의: \'개념 박스화\'를 통한 지문 구조 분석');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_127', 'lesson_note', '강의 개요', '조창훈', '본 내용은 수능 비문학 독서 지문, 특히 철학이나 사회 이론과 같이 복잡한 개념이 등장하는 글을 효과적으로 분석하고 이해하기 위한 1:1 코칭 세션입니다. 강사는 \'개념 박스화\'라는 핵심 전략을 통해, 학생들이 지문의 정보를 구조적으로 정리하고 문제 해결 능력을 향상시키는 방법을 집중적으로 교육합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_128', 'lesson_note', '핵심 독해 전략: 개념 박스화', '조창훈', '강사가 제시한 가장 중요한 독해 방법론은 \'개념 박스화\'입니다. 이는 지문 속 대립되거나 구분되는 핵심 개념들을 머릿속에 별개의 \'박스\'로 설정하고, 관련된 모든 정보를 해당 박스에 체계적으로 담는 훈련입니다.\n\n- **목표**: 정보의 혼란을 방지하고, 겉보기에 많아 보이는 정보량을 단순화하여 관리하는 것.\n- **방법**: 글을 읽는 동안 각각의 문장이나 구절이 어떤 핵심 개념(박스)에 속하는지 의식적으로 연결하며 읽습니다. (예: \'헤겔\' 박스, \'뒤르켐\' 박스, \'이\' 박스, \'기\' 박스)\n- **효과**: 개념 간의 관계와 지문 전체의 구조를 명확하게 파악할 수 있으며, 출제자의 의도를 파악하는 데 유리합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_129', 'lesson_note', '첫 번째 지문 분석: 헤겔과 뒤르켐의 시민사회론', '조창훈', '첫 번째 예시 지문인 \'19세기 시민 사회론\'을 통해 개념 박스화 전략의 기초를 설명했습니다.\n\n- **구조 파악**: 1문단에서 \'사회 이론\'을 정의하고, 그 예시로 \'19세기 시민 사회론\'을 제시합니다.\n- **개념 박스 설정**: 2문단의 **헤겔**과 3문단의 **뒤르켐**을 각각 별개의 박스로 설정합니다.\n- **정보 분류**: 지문을 읽으며 \'프로이센\', \'산업 자본주의\' 등은 헤겔 박스에, \'프랑스 혁명\', \'샤플리에 법\' 등은 뒤르켐 박스에 넣으며 정보를 구분하여 정리할 것을 강조했습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_130', 'lesson_note', '두 번째 지문 심층 분석: 율곡 이이의 수기치인과 이기론', '조창훈', '율곡 이이의 사상을 다룬 두 번째 지문은 더 복잡한 구조를 가지며, 다층적 개념 박스화를 적용하는 심화 훈련으로 사용되었습니다.\n\n### 1단계 박스화: 수기(修己) vs 치인(治人)\n- 지문의 기본 틀인 유학의 목표 \'수기치인\'을 두 개의 큰 박스로 설정합니다.\n- **수기 (노란 박스)**: 개인의 수양. \'수신(修身)\'과 \'수양론\'이 여기에 해당합니다.\n- **치인 (초록 박스)**: 타인과 사회를 다스림. \'제가(齊家)\', \'치국(治國)\', \'평천하(平天下)\'와 \'경세론\'이 여기에 해당합니다.\n\n### 2단계 박스화: 이(理) vs 기(氣)\n- 수기치인을 설명하는 도구로 제시된 \'이기론\'을 새로운 두 개의 박스로 설정합니다.\n- **이 (理, 파란 박스)**: 만물의 보편적 원리이자 법칙. 형체가 없고 시공간 제약을 받지 않으며, **불변(不變)**합니다.\n- **기 (氣, 빨간 박스)**: 만물을 구성하는 물질적 요소. 형체가 있고 시공간 제약을 받으며, **끊임없이 변화(變化)**합니다.\n- **핵심 관계**: 이와 기는 서로 구별되면서도 분리되지 않고 **항상 함께 존재**합니다 (\'이기지묘\').\n\n### 수양론과 경세론에 이기론 적용\n- 강사는 앞서 설정한 \'이\'와 \'기\'라는 물감을 \'수기\'와 \'치인\'이라는 도화지에 그리는 과정으로 비유하며 설명했습니다.\n- **수양론 (수기)**: 성인과 일반인은 동일한 **\'이(理)\'**를 가졌지만, 기질의 차이, 즉 **\'기(氣)\'**가 다르기 때문에 구별됩니다. 따라서 수양이란 잘못된 \'기\'를 교정하여 본래 선한 \'이\'를 드러나게 함으로써 성인이 되는 과정입니다.\n- **경세론 (치인)**: 사회 문제에도 동일한 구조가 적용됩니다. \'사회적 폐단\'은 잘못된 **\'기\'**에 해당하고, 실현해야 할 \'천도(天道)\'는 **\'이\'**에 해당합니다. 따라서 사회 개혁은 \'기\'에 해당하는 \'법제(法制)\'를 바꾸어 \'이\'를 실현하는 과정입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_131', 'lesson_note', '법제 개혁론의 단계적 분석', '조창훈', '율곡의 법제 개혁론은 \'기\'에서 \'이\'로 나아가는 단계적 구조를 보이며, 이는 출제 포인트가 될 수 있음을 강조했습니다.\n\n- **\'기(氣)\'에 해당하는 법제**: 시대에 따라 변할 수 있는 것.\n  - **수교(受敎)**: 특정 사건 해결을 위한 개별적 법령.\n  - **록(錄)**: \'수교\' 중 폐단이 없고 유효성이 확인된 것들을 모은 법전.\n- **\'이(理)\'에 해당하는 법제**: 영구히 변하지 않는 것.\n  - **대전(大典)**: \'록\'의 규정들이 오랜 시간을 거쳐 영구한 규범으로 확립된 것. \'경국대전\'이 예시이며, 이는 \'양법(良法)\' 또는 \'조종성헌(祖宗成憲)\'으로 불리며 개정 대상이 아닙니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_132', 'lesson_note', '강사의 핵심 요약 및 강조점', '조창훈', '- **출제자의 의도**: 비문학 지문은 교육이 아닌 **문제 출제를 목적**으로 구성됩니다. 모든 문장은 문제의 재료가 되거나, 그 재료를 위한 \'빌드업\' 과정의 일부입니다.\n- **구조적 독해의 중요성**: 세부 내용에 매몰되지 말고, \'수기 vs 치인\', \'이 vs 기\'와 같은 큰 틀(박스)을 먼저 잡고 정보를 정리해야 글이 쉽게 읽힙니다.\n- **적극적 개념 치환**: \'천도\', \'왕도\', \'조종성헌\' 등 다른 표현이 나오더라도 이를 핵심 개념인 **\'이(理)\'**로, \'사회 폐단\', \'기질\', \'법제\' 등은 **\'기(氣)\'**로 즉시 치환하여 읽는 연습이 필요합니다.\n- **전제 조건 문제 유형**: \'대전\'이 되기 위한 조건을 물을 때, \'대전\'의 직접적 조건뿐만 아니라 그 전 단계인 \'록\'과 \'수교\'의 전제 조건까지 포함될 수 있음을 유의해야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_133', 'lesson_note', '학생에게 제시된 과제', '조창훈', '강사는 학생에게 배운 \'개념 박스화\' 전략이 완전히 체화될 때까지, 동일한 지문을 사용하여 **스스로 여러 번 반복해서 분석하고 읽는 연습**을 할 것을 강력히 권고했습니다. 이론을 아는 것과 스스로 적용하는 것은 다르기 때문에, 반복 훈련을 통해 이 독해법을 자신의 것으로 만드는 것이 중요하다고 강조했습니다.\n\n# 현대 문학사 강의: 개화기 신체시부터 1920년대 주요 작품 심층 분석');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_134', 'lesson_note', '강의 개요', '조창훈', '이번 강의는 한국 현대 문학사 초기, 특히 개화기부터 1920년대까지의 주요 시 작품들을 중심으로 진행되었습니다. 최남선의 「경부철도가」와 「해에게서 소년에게」를 통해 신체시의 등장과 계몽주의적 성격을 분석하고, 주요한의 「불놀이」와 홍사용의 「나는 왕이로소이다」를 통해 낭만주의와 산문시의 특징, 그리고 시대적 배경이 작품에 미치는 영향을 심도 있게 다루었습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_135', 'lesson_note', '주요 작품 심층 분석', '조창훈', '### 최남선, 「경부철도가」 (1908)\n*   **갈래**: 7·5조 음수율을 지닌 창가(唱歌)로, 아직 정형시의 틀을 벗어나지 못한 과도기적 작품입니다.\n*   **주제**: 경부선 철도 개통을 통해 문명개화와 새로운 시대에 대한 기대감을 노래했습니다.\n*   **상징**: \'기차\'는 거스를 수 없는 강력한 힘을 지닌 근대 문명의 상징물입니다.\n*   **의의**: 계몽적 성격이 강하며, 이후 김소월 시에 영향을 준 7·5조 율격의 시초라는 점에서 문학사적 의미를 가집니다.\n\n### 최남선, 「해에게서 소년에게」 (1908)\n*   **갈래**: 한국 최초의 신체시(新體詩)로 평가받습니다.\n*   **구조**: \'바다\'(근대 문명, 신세계)가 \'소년\'(미래의 희망, 순수한 존재)에게 말하는 형식으로, \'육지\'(전근대적 구습, 방해물)와 대립적 구도를 이룹니다.\n*   **주제**: 구시대의 낡은 것을 극복하고 신세계를 이끌어갈 소년 세대에 대한 강한 기대와 희망을 표현했습니다.\n*   **표현**: \'철썩철썩\'과 같은 역동적 의성어와 힘찬 어조를 사용하여 개화에 대한 열망을 드러내며, 전반적으로 낙관적인 태도를 보입니다.\n\n### 주요한, 「불놀이」 (1919)\n*   **갈래**: 한국 최초의 자유시 중 하나로, 산문시의 특징도 지니고 있습니다.\n*   **사조**: 개인의 감정을 격정적으로 표출하는 낭만주의의 대표작으로, 감정 절제를 중시하는 이미지즘(정지용)과 대조됩니다.\n*   **주제**: 사랑을 잃은 청년의 고뇌와 절망, 그리고 삶에 대한 열망 사이의 내면적 갈등을 다룹니다.\n*   **상징**: \'불\'(삶, 열정, 생명력, 파괴적 욕망)과 \'강물\'(죽음, 슬픔, 망각)의 대립적 이미지를 통해 화자의 복잡한 심리를 형상화했습니다.\n\n### 홍사용, 「나는 왕이로소이다」 (1922)\n*   **갈래**: 행과 연의 구분이 없는 산문시입니다.\n*   **해석**: 일제강점기라는 시대 현실을 바탕으로 해석해야 하는 반영론적 작품입니다.\n*   **주제**: 식민지 지식인의 깊은 비애와 민족적 설움을 노래했습니다.\n*   **상징**: 화자인 \'나\'는 \'눈물의 왕\'으로, 슬픔과 울음밖에 없는 식민지 민중을 상징하며, \'어머니\'는 조국을 의미합니다.\n*   **특징**: 전반적으로 희망이 부재한 비관적이고 애상적인 분위기가 지배적입니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_136', 'lesson_note', '핵심 문학사 개념 정리', '조창훈', '*   **창가와 신체시**: 고전 시가에서 현대시로 넘어가는 과도기적 형태로, \'창가\'는 7·5조 등 정형적 율격을 지닌 노래이며, \'신체시\'는 내용과 형식 면에서 보다 자유로운 새로운 시도를 보였습니다.\n*   **음수율의 변화**: 전통적인 4·4조(가사, 시조)에서 벗어나 7·5조(「경부철도가」, 김소월 시)라는 새로운 율격이 시도되었습니다.\n*   **문학 사조의 흐름**: 사회적 메시지를 중시하는 계몽주의(초기 신체시)에서 출발하여, 점차 개인의 내면과 감정을 중시하는 낭만주의(「불놀이」)로 전환되는 양상을 보였습니다.\n*   **새로운 시 형식의 등장**: 정형률에서 벗어난 자유시(「불놀이」)와 행 구분이 없는 산문시(「나는 왕이로소이다」)가 등장하여 표현의 자유를 크게 확장시켰습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_137', 'lesson_note', '고전 시가 비교 분석 (연습 문제 풀이)', '조창훈', '「해에게서 소년에게」의 자신감 넘치는 화자 태도와 비교하기 위해 여러 고전 시조를 분석했습니다.\n*   **지조와 절개**: 성삼문의 시조에 나타난 \'낙락장송\'과 \'독야청청\'은 세조의 왕위 찬탈에 굴하지 않는 충신의 굳은 절개를 상징합니다.\n*   **호방한 기개**: 김종서의 시조는 북방 변방을 지키는 장수로서의 위엄과 호방한 기상을 보여줍니다.\n*   **간신 비판**: 이존오의 시조는 \'구름\'(간신)이 \'햇빛\'(임금)을 가리는 모습을 통해 권신 신돈을 우의적으로 비판합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_138', 'lesson_note', '「해에게서 소년에게」와 「동심가」 비교', '조창훈', '두 작품은 개화기라는 공통된 시대적 배경을 가집니다. 모두 낡은 것을 버리고 새로운 시대를 맞이하자는 계몽적 메시지를 담고 있으며, 현실에 대한 구체적인 대응 방식(하나가 되자, 마음을 합치자 등)을 제시한다는 공통점이 있습니다. 다만 「해에게서 소년에게」는 자유로운 형식의 신체시인 반면, 이중원의 「동심가」는 4·4조 율격의 창가 형식을 따르는 차이가 있습니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_139', 'lesson_note', '강사의 시 분석 방법론', '조창훈', '1.  **작품 내적으로 접근**: 시를 처음 읽을 때는 외부 정보를 배제하고 작품 속 세계관과 표현을 있는 그대로 받아들입니다.\n2.  **구조적 파악**: 긍정적 시어와 부정적 시어, 대립적 공간(예: 바다/육지)과 상징을 구분하여 작품의 전체적인 밑그림을 그립니다.\n3.  **외재적으로 확장**: 작품 분석이 끝나면 작가, 시대적 배경(반영론) 등 외부 정보와 연결하여 의미를 심화시킵니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_140', 'lesson_note', '강사의 주요 강조 사항 및 시험 대비 전략', '조창훈', '*   **문학사적 의의 파악**: 각 작품이 \'최초의 신체시\', \'최초의 자유시\' 등 문학사에서 차지하는 위치와 역사적 의미를 정확히 이해하는 것이 중요합니다.\n*   **꼼꼼한 학습 태도**: 수업 시간에 간단히 언급하고 넘어가는 부수적인 작품이라도 시험에 출제될 수 있으므로(예: 이상화의 \'나의 침실로\' 출제 사례), 프린트의 모든 내용을 꼼꼼히 학습해야 합니다.\n*   **핵심 개념 숙지**: 낭만주의, 이미지즘, 감정 절제, 반영론 등 주요 문학 용어의 개념을 명확히 구분하고 숙지해야 합니다.');
INSERT INTO ai_chat_references (id, source, topic, speaker, content) VALUES ('ref_lesson_141', 'lesson_note', '다음 학습 안내', '조창훈', '다음 강의에서는 현대시의 중요한 인물인 **정지용** 시인에 대해 다룰 예정입니다. 그의 시 세계를 대표하는 **이미지즘** 기법과 **감정 절제**의 특징이 이번 시간에 다룬 주요한의 낭만주의 시와 어떻게 다른지 비교하며 학습할 것을 예고했습니다.');
